INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('arrive', 'en', 'Arrive in the room', '5-4-3-2-1 Somatic Grounding', 'A 2-minute reset to anchor in physical reality when your mind is racing.', '["Name five neutral things you can see around you.","Notice four things you can physically touch or feel against your skin.","Identify three distinct sounds in your environment.","Notice two scents or aromas nearby.","Acknowledge one steady sensation right where you are."]', 'Interrupts anxious cognitive spinning by redirecting sensory processing to present, safe sensory signals.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('arrive', 'es', 'Llegar al espacio presente', 'Enraizamiento somático 5-4-3-2-1', 'Una pausa de 2 minutos para conectar con la realidad tangible cuando la mente se acelera.', '["Nombra cinco objetos neutros que puedas ver a tu alrededor.","Siente cuatro texturas o puntos de apoyo en tu cuerpo.","Identifica tres sonidos distintos en el ambiente.","Percibe dos aromas sutiles o sensaciones en el aire.","Reconoce una sensación firme en este preciso momento."]', 'Interrumpe el ciclo de rumiación ansiosa enviando al sistema nervioso señales de seguridad en el aquí y ahora.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('arrive', 'pt-BR', 'Chegar ao espaço presente', 'Aterramento somático 5-4-3-2-1', 'Uma pausa de 2 minutos para ancorar na realidade quando os pensamentos estiverem acelerados.', '["Identifique cinco coisas neutras que você pode ver ao seu redor.","Perceba quatro pontos de contato do corpo com o ambiente.","Reconheça três sons presentes neste momento.","Note dois aromas ou a temperatura do ar.","Sinta uma sensação de firmeza onde você está agora."]', 'Alivia o turbilhão mental redirecionando a atenção para estímulos sensoriais concretos e seguros.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('orient', 'en', 'Today, not then', 'Orientation to the Present', 'Remind your nervous system of the exact temporal and spatial safety of today.', '["State your name aloud or in your mind.","Say today’s date, the current year, and where you are sitting or standing.","Look around and find one physical detail that proves you are not in the difficult past.","Take one unhurried breath as you settle into this certainty."]', 'Helps counter trauma-related activation by differentiating past distress from current safety.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('orient', 'es', 'Hoy, no en aquel momento', 'Orientación hacia el presente', 'Recuérdale a tu cuerpo en qué día y lugar seguro te encuentras hoy.', '["Di tu nombre en voz baja o en silencio.","Reconoce la fecha de hoy, el año actual y el lugar donde te encuentras.","Observa un detalle en la habitación que demuestre que el pasado difícil ya no está ocurriendo.","Respira con calma, reconociendo la estabilidad de este instante."]', 'Diferencia los recuerdos dolorosos de la realidad actual, ofreciendo serenidad al sistema nervioso.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('orient', 'pt-BR', 'Hoje, não naquele tempo', 'Orientação para o momento presente', 'Lembre seu corpo do momento exato e da segurança do dia de hoje.', '["Diga seu nome em voz baixa ou em pensamento.","Reconheça a data de hoje, o ano e o local onde você está.","Olhe ao redor e encontre um detalhe que comprove que você não está no passado difícil.","Respire sem pressa, permitindo-se sentir a firmeza deste momento."]', 'Ajuda a desarmar alertas antigos, mostrando que o momento presente é diferente do que já passou.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('release', 'en', 'Unclench one thing', 'Somatic Micro-Release', 'Notice where tension gathers and give permission for just one small area to soften.', '["Notice your jaw: allow your teeth to part and your tongue to rest on the floor of your mouth.","Notice your shoulders: let them drop away from your ears by half an inch.","Notice your hands: let your fingers uncurl gently in your lap.","Choose just one area to soften. You do not have to relax everything."]', 'Breaks the unconscious habit of bracing against imaginary threats.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('release', 'es', 'Soltar un solo punto', 'Liberación somática sutil', 'Identifica la tensión acumulada y permite que una pequeña zona del cuerpo descanse.', '["Observa la mandíbula: separa ligeramente los dientes y deja que la lengua descanse.","Observa los hombros: permíteles descender suavemente unos milímetros.","Observa las manos: abre los dedos con naturalidad sobre el regazo.","Elige un solo punto para aflojar. No hace falta relajar todo a la vez."]', 'Disminuye la postura defensiva involuntaria y permite que el cuerpo reconozca el descanso.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('release', 'pt-BR', 'Soltar um ponto de tensão', 'Alívio somático sutil', 'Perceba onde você está acumulando tensão e dê permissão para suavizar apenas uma área.', '["Observe o maxilar: afaste os dentes e deixe a língua repousar suavemente.","Observe os ombros: permita que desçam um pouquinho, longe das orelhas.","Observe as mãos: desfaça a rigidez dos dedos no seu colo.","Escolha apenas uma parte para afrouxar. Não é preciso relaxar tudo de uma vez."]', 'Desfaz a postura de alerta contínuo, transmitindo alívio imediato ao corpo.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('name', 'en', 'Name what is here', 'Notice, Feel, Need', 'Separate facts from fearful predictions by completing three grounding sentences.', '["Say to yourself: \"I notice...\" (name an objective, observable fact).","Say to yourself: \"I feel...\" (name the emotional or physical sensation without judgment).","Say to yourself: \"What I need right now is...\" (name a small, immediate, realistic support)."]', 'Cultivates emotional literacy and shifts cognitive appraisal from panic to constructive care.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('name', 'es', 'Nombrar lo que está aquí', 'Observar, sentir y necesitar', 'Diferencia los hechos objetivos de las suposiciones dolorosas mediante tres frases sencillas.', '["Completa en silencio: \"Noto...\" (menciona un hecho observable y claro).","Completa en silencio: \"Siento...\" (describe la emoción o sensación sin juzgarla).","Completa en silencio: \"Lo que necesito en este instante es...\" (identifica un cuidado concreto y posible)."]', 'Promueve la claridad emocional y permite responder con compasión en lugar de reaccionar con pánico.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('name', 'pt-BR', 'Nomear o que está presente', 'Perceber, sentir e cuidar', 'Separe os fatos concretos das preocupações futuras com três frases acolhedoras.', '["Complete mentalmente: \"Eu percebo...\" (descreva um fato observável e real).","Complete mentalmente: \"Eu sinto...\" (nomeie a sensação ou emoção sem autocrítica).","Complete mentalmente: \"O que eu preciso agora é...\" (um cuidado simples e realizável)."]', 'Organiza o mundo interno e transforma a sobrecarga em clareza sobre o próximo passo.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('weather', 'en', 'Emotional weather report', 'Defusion & Non-Attachment', 'Observe your internal state as a temporary climate rather than your core identity.', '["Pause and check your internal horizon: Is it stormy, overcast, foggy, bright, or shifting?","Say: \"Right now, the weather inside is [foggy / turbulent / brisk].\"","Notice that you are the sky that holds the weather, not the storm itself.","Let the clouds pass across your awareness without pushing them away."]', 'Teaches mindfulness defusion, reminding you that emotions rise, peak, and change naturally.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('weather', 'es', 'Informe del clima interior', 'Desidentificación y calma', 'Observa tu estado anímico como un clima pasajero y no como una definición permanente de quién eres.', '["Haz una pausa e indaga: ¿hay tormenta, niebla, sol suave o viento cambiante?","Reconoce con suavidad: \"En este momento, mi clima interior es [pesado / nublado / templado].\"","Recuerda que tú eres el cielo que contiene el clima, no la tormenta en sí.","Deja que las nubes se muevan a su ritmo sin forzarlas a desaparecer."]', 'Ayuda a contemplar las emociones sin apego, sabiendo que toda sensación se transforma con el tiempo.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('weather', 'pt-BR', 'Previsão do tempo interior', 'Descompressão e serenidade', 'Veja suas emoções como um clima temporário, e não como uma verdade permanente sobre você.', '["Faça uma pausa e repare: há chuva, névoa, sol ou ventos inquietos por dentro?","Diga a si mesmo: \"Neste momento, meu clima interno está [agitado / nublado / sereno].\"","Lembre-se de que você é o céu que acolhe o clima, e não a tempestade.","Deixe que as nuvens sigam seu curso natural sem tentar lutar contra elas."]', 'Cultiva o distanciamento saudável, lembrando que todo estado de ânimo se transforma com o tempo.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('next', 'en', 'The next workable thing', 'Pragmatic Action Alignment', 'When everything feels impossible, identify just one small action that belongs to the next ten minutes.', '["Acknowledge the overwhelm: \"I cannot fix the whole picture right now.\"","Ask: \"What is one workable action that belongs strictly to the next ten minutes?\"","Keep it small: drink a glass of water, close three tabs, or reply to one essential note.","Allow that single action to be enough for right now."]', 'Restores human agency without demanding false enthusiasm or perfection.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('next', 'es', 'El próximo paso viable', 'Claridad en la acción cotidiana', 'Cuando todo parece abrumador, encuentra una sola cosa posible para los próximos diez minutos.', '["Reconoce la situación con honestidad: \"No puedo resolverlo todo en este momento.\"","Pregúntate: \"¿Cuál es una acción sencilla y posible para los próximos diez minutos?\"","Elige algo breve: beber un vaso de agua, organizar un rincón o responder un mensaje pendiente.","Permite que esa pequeña acción sea suficiente por ahora."]', 'Devuelve la sensación de capacidad personal sin exigir soluciones heroicas.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('next', 'pt-BR', 'O próximo passo possível', 'Ação gentil e realista', 'Quando tudo parecer demais, encontre uma única atitude realizável para os próximos dez minutos.', '["Acolha o cansaço com honestidade: \"Eu não preciso resolver tudo hoje.\"","Pergunte-se: \"Qual é uma pequena atitude viável para os próximos dez minutos?\"","Mantenha a simplicidade: beber um copo de água, fechar abas abertas ou lavar o rosto.","Permita que esse único passo seja o bastante por enquanto."]', 'Restaura a confiança em sua própria capacidade sem cobranças desmedidas.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('kindly', 'en', 'The three-part kindness pause', 'Self-Compassion Foundation', 'A gentle structure adapted from Kristin Neff: mindfulness, common humanity, and kind support.', '["Mindfulness: Place a hand over your heart or on your arm. Say: \"This is a hard moment.\"","Common Humanity: Remind yourself: \"Struggle is part of being human. I am not alone in this feeling.\"","Self-Kindness: Ask: \"What kind, steady word or action would support me right now?\""]', 'Stimulates the mammalian soothing system through warm touch and supportive language.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('kindly', 'es', 'La pausa de la ternura en tres tiempos', 'Fundamentos de la autocompasión', 'Un espacio de cuidado inspirado en la autocompasión: presencia, humanidad compartida y amabilidad.', '["Presencia: Pon una mano en tu pecho o en tu brazo. Di en silencio: \"Este es un momento difícil.\"","Humanidad compartida: Recuérdate: \"Sentir dificultad es parte de la experiencia humana. No estoy a solas en esto.\"","Amabilidad propia: Pregúntate: \"¿Qué palabra honesta y cálida necesito escuchar de mí en este instante?\""]', 'Activa el sistema de calma y consuelo a través del contacto suave y el tono comprensivo.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('kindly', 'pt-BR', 'A pausa da gentileza em três passos', 'Autocompaixão no dia a dia', 'Um refúgio acolhedor com presença, humanidade compartilhada e apoio honesto.', '["Presença: Coloque uma das mãos sobre o peito ou no braço. Diga: \"Este é um momento doloroso.\"","Humanidade compartilhada: Lembre-se: \"A dificuldade faz parte da vida de todos nós. Não estou só.\"","Gentileza: Pergunte a si mesmo: \"Que cuidado simples ou palavra amiga eu posso me oferecer agora?\""]', 'Ativa circuitos neurais de acolhimento e diminui a autocrítica severa.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('friend', 'en', 'Borrow a kinder voice', 'Perspective Re-centering', 'Offer yourself the same compassionate wisdom you naturally extend to someone you care about.', '["Think of what you are struggling with today.","Imagine a dear friend coming to you with the exact same situation.","Write down what you would say to them: the tone, the reassurance, the patience.","Now, read those exact words back to yourself, using your own name."]', 'Bypasses internalized harsh self-judgment by activating well-established empathy pathways.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('friend', 'es', 'Prestar una voz más comprensiva', 'Cambio de perspectiva afectuosa', 'Bríndate a ti la misma mirada comprensiva que le entregarías a un ser querido.', '["Trae a la mente la dificultad que estás atravesando hoy.","Imagina que un buen amigo llega a contarte exactamente esa misma situación.","Escribe qué le dirías: las palabras de ánimo, la comprensión y el tono de apoyo.","Ahora lee ese mensaje hacia ti, llamándote por tu propio nombre."]', 'Neutraliza la autocrítica excesiva aprovechando la capacidad natural de empatía que ya posees.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('friend', 'pt-BR', 'Adotar uma voz mais compreensiva', 'Empatia consigo mesmo', 'Ofereça a si a mesma compaixão e paciência que você ofereceria a alguém querido.', '["Pense no desafio que você está enfrentando hoje.","Imagine um amigo querido passando pela exata mesma situação e procurando seu apoio.","Escreva o que você diria a ele: o tom carinhoso, a escuta e a compreensão sincera.","Agora, leia essas palavras para si mesmo, chamando-se pelo seu próprio nome."]', 'Suaviza o diálogo interno duro e desperta o cuidado genuíno que você costuma reservar aos outros.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('boundary', 'en', 'A clean boundary sentence', 'Grounded Interpersonal Clarity', 'Communicate what you can and cannot do without defensiveness, over-explaining, or guilt.', '["Identify what is being requested of your time or energy.","Formulate the boundary using the clean pattern: \"I cannot do X. I can do Y.\"","Resist adding long justifications, medical reasons, or multiple apologies.","Say it with warm clarity, allowing the other person their natural reaction."]', 'Reduces anxiety around setting limits by avoiding the exhaustion of over-explaining.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('boundary', 'es', 'Un límite con serenidad', 'Claridad en las relaciones', 'Expresa lo que puedes y lo que no puedes hacer con firmeza tranquila, sin rodeos ni culpas.', '["Identifica qué compromiso o demanda está agotando tu energía.","Usa una fórmula directa: \"En este momento no puedo hacer X. Con gusto puedo aportar Y.\"","Evita justificaciones interminables o disculpas excesivas que diluyan tu decisión.","Comunícalo con calidez y permite que la otra persona procese su propia respuesta."]', 'Protege tu bienestar y tus relaciones al sustituir el resentimiento por acuerdos claros.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('boundary', 'pt-BR', 'Um limite claro e sereno', 'Relações conscientes', 'Comunique o que você pode e o que não pode assumir, com tranquilidade e sem culpa.', '["Reconheça o que está sendo pedido e o impacto na sua energia.","Use uma estrutura simples: \"Eu não consigo fazer X no momento. O que posso oferecer é Y.\"","Resista à tentação de criar justificativas longas ou pedir desculpas desnecessárias.","Fale com gentileza e deixe espaço para a outra pessoa acolher a resposta."]', 'Previne a sobrecarga e fortalece a convivência por meio da transparência e do respeito mútuo.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('listen', 'en', 'Ask before fixing', 'Supportive Inquiry', 'Show up for a loved one without falling into the trap of unsolicited advice or quick fixes.', '["Notice when someone shares pain: catch the urge to jump to advice or solutions.","Offer the supportive four-way check: \"Do you want listening, ideas, practical help, or just company right now?\"","Honor their answer completely.","Stay present in the room with whatever they choose."]', 'Creates true emotional safety by keeping the speaker in charge of their own process.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('listen', 'es', 'Preguntar antes de resolver', 'Escucha consciente', 'Acompaña a quien te importa sin caer en consejos apresurados ni soluciones impuestas.', '["Cuando alguien comparta una dificultad, frena el impulso automático de solucionar el problema.","Pregunta con respeto: \"¿Prefieres que te escuche, que pensemos ideas, ayuda práctica o solo compañía?\"","Acepta con agrado lo que la persona te responda.","Permanece presente con sencillez, sin intentar cambiar lo que siente."]', 'Genera confianza mutua y respeta el ritmo de quien necesita ser escuchado de verdad.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('listen', 'pt-BR', 'Perguntar antes de aconselhar', 'Escuta atenta e afetuosa', 'Esteja ao lado de quem você ama sem a ansiedade de tentar consertar tudo de imediato.', '["Quando alguém desabafar, perceba o impulso de dar conselhos e respire fundo.","Faça uma pergunta acolhedora: \"Você prefere apenas desabafar, trocar ideias, ajuda prática ou só uma companhia?\"","Respeite plenamente a resposta da pessoa.","Esteja presente de coração aberto, sem pressa para mudar o que ela está sentindo."]', 'Cria um ambiente seguro onde o outro se sente compreendido e respeitado em seu próprio tempo.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('grief', 'en', 'Make a small place for grief', 'Gentle Container Practice', 'Give sorrow a dedicated window of tender attention without demanding that it be resolved.', '["Choose a simple container: ten minutes, a lighted candle, a specific chair, or a song.","Sit down and say: \"For these ten minutes, I don’t have to pretend I am fine.\"","Allow tears, memories, or silence to unfold without needing to tidy them up.","When the time ends, thank yourself, blow out the candle, and take a sip of water."]', 'Prevents emotional numbness by offering grief safe, bounded time to be honored.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('grief', 'es', 'Un rincón para el duelo', 'Espacio contenido y amable', 'Dedica unos minutos para estar con tu tristeza sin la exigencia de superarla de inmediato.', '["Prepara un espacio sencillo: diez minutos en calma, una vela encendida o una melodía suave.","Toma asiento y dite: \"Durante estos minutos, no tengo que aparentar que todo está resuelto.\"","Permite que surjan lágrimas, recuerdos o silencios sin intentar ordenarlos ni corregirlos.","Al terminar el tiempo, agradece tu valor, apaga la vela y toma un sorbo de agua fresca."]', 'Evita el embotamiento emocional brindando al dolor un lugar seguro y respetuoso donde expresarse.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('grief', 'pt-BR', 'Um espaço para o luto', 'Acolhimento sereno da dor', 'Reserve um momento de carinho para a sua saudade sem a cobrança de superá-la agora.', '["Escolha um momento simples: dez minutos de silêncio, uma vela acesa ou uma música tranquila.","Acomode-se e diga com carinho: \"Por estes minutos, eu não preciso fingir que está tudo bem.\"","Deixe que as lágrimas, memórias ou quietudes venham sem pressa de encontrar explicações.","Ao final do tempo, respire fundo, agradeça pela pausa e beba um gole de água."]', 'Ajuda a processar perdas significativas com dignidade, sem reprimir nem se desorganizar.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('memory', 'en', 'Continuing bond', 'Meaningful Legacy Reflection', 'Honor a loss by recognizing the values, stories, and love that continue forward in you.', '["Bring to mind the person, place, or season of life you miss.","Complete the sentence: \"Because you existed, I now carry...\"","Write down one value, kindness, recipe, or perspective they left with you.","Recognize that love changes form, but the bond remains alive in how you live."]', 'Re-frames grief from an abrupt severed tie into an enduring, meaningful relationship.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('memory', 'es', 'El lazo que permanece', 'Memoria y continuidad del amor', 'Honra una pérdida reconociendo los valores y aprendizajes que siguen vivos en tu caminar.', '["Trae a tu memoria a esa persona, lugar o etapa entrañable que extrañas.","Completa esta reflexión: \"Gracias a que estuviste en mi vida, hoy conservo...\"","Anota una enseñanza, una sonrisa, una costumbre o un valor que haya dejado en ti.","Reconoce que el amor no desaparece, sino que se transforma en la manera en que cuidas tu presente."]', 'Transforma el vacío de la ausencia en una presencia afectuosa que acompaña y da sentido.');
INSERT OR REPLACE INTO practice_translations (practice_id, locale, title, subtitle, description, steps, why_it_helps) VALUES ('memory', 'pt-BR', 'O vínculo que continua', 'Memória afetiva e legado', 'Honre uma ausência reconhecendo o amor e as marcas bonitas que continuam vivas em você.', '["Traga ao pensamento a pessoa, o lugar ou a fase da vida da qual você sente saudade.","Escreva ou reflita: \"Por você ter feito parte da minha história, hoje eu carrego...\"","Lembre-se de um gesto, ensinamento ou carinho que você herdou dessa convivência.","Perceba que o amor não se desfaz: ele se expressa nas escolhas gentis que você faz hoje."]', 'Alivia o sentimento de ruptura, integrando as lembranças queridas como fonte de força cotidiana.');

