INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('anxious-restless', 'en', 'Anxious, wired, restless', 'Gentle botanical support and somatic breathing for an alert nervous system seeking safety.', '["Chamomile (Matricaria chamomilla)","Lemon Balm (Melissa officinalis)","Oat Straw (Avena sativa)"]', '["Extended exhale: inhale for 4 counts, exhale softly for 6 counts for 90 seconds","Somatic sensory check: 5-4-3-2-1 arrival in the room","Warm herbal infusion before bedtime"]', '["Avoid high caffeine late in the day","Consult a clinician if taking sedative medications"]', 'Safe in standard culinary tea amounts; discuss higher botanical doses with your midwife or physician.', '["Panic symptoms lasting over an hour","Chest pain or difficulty breathing","Persistent severe anxiety affecting basic daily living"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('anxious-restless', 'es', 'Inquietud, nerviosismo y alerta constante', 'Plantas tradicionales y respiración consciente para acompañar a un sistema nervioso que busca calma.', '["Manzanilla dulce (Matricaria chamomilla)","Toronjil o melisa (Melissa officinalis)","Paja de avena (Avena sativa)"]', '["Exhalación prolongada: inhala en 4 tiempos y exhala con calma en 6 tiempos durante minuto y medio","Contacto con los sentidos para anclarte en el presente","Infusión tibia de hierbas al caer la tarde"]', '["Moderar el café y bebidas energéticas a partir del mediodía","Consultar con profesionales si se toman fármacos ansiolíticos"]', 'Adecuado en infusiones suaves habituales; consulta con tu especialista antes de concentrados o extractos.', '["Episodios de pánico prolongados","Opresión en el pecho o dificultad para respirar","Malestar continuo que impida el descanso y las labores diarias"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('anxious-restless', 'pt-BR', 'Inquietação, agitação e alerta constante', 'Apoio botânico gentil e respiração consciente para acalmar um corpo em estado de vigilância.', '["Camomila (Matricaria chamomilla)","Erva-cidreira / Melissa (Melissa officinalis)","Palha de aveia (Avena sativa)"]', '["Expiração prolongada: inspire contando até 4 e expire suavemente contando até 6 por 90 segundos","Pausa somática percebendo o apoio dos pés no chão","Chá morno ao entardecer em ambiente acolhedor"]', '["Evitar cafeína e telas brilhantes no fim do dia","Conversar com seu médico se usar medicamentos calmantes"]', 'Tranquilo em chás caseiros leves; consulte sua equipe de saúde antes de usar extratos concentrados.', '["Crises de pânico frequentes","Falta de ar intensa ou dor torácica","Ansiedade persistente que prejudique a rotina básica"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('trouble-sleeping', 'en', 'Trouble falling or staying asleep', 'Restoring the natural circadian rhythm with evening rituals, nervine teas, and body quietness.', '["Passionflower (Passiflora incarnata)","Valerian Root (Valeriana officinalis)","Magnesium-rich foods (pumpkin seeds, almonds)"]', '["Consistent wake time seven days a week","Dim indoor lighting 60 minutes before bed","Warm foot bath or chamomile tea ritual"]', '["Valerian can cause morning grogginess in some individuals; start with small servings","Do not combine with prescription sleeping pills"]', 'Valerian is generally avoided in pregnancy; rely on chamomile and gentle wind-down rhythms instead.', '["Chronic insomnia lasting more than a month","Loud snoring, choking, or gasping during sleep (screening for sleep apnea)","Extreme daytime exhaustion causing unsafe driving"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('trouble-sleeping', 'es', 'Dificultad para conciliar o mantener el sueño', 'Armonizar el ritmo natural mediante rituales vespertinos, plantas sedantes suaves y descanso mental.', '["Pasiflora o flor de la pasión (Passiflora incarnata)","Valeriana (Valeriana officinalis)","Alimentos ricos en magnesio (semillas de calabaza, almendras)"]', '["Mantener la misma hora al despertar todos los días","Bajar la intensidad de las luces una hora antes de dormir","Baño de pies tibio o infusión reconfortante"]', '["La valeriana puede causar somnolencia matutina en algunas personas; comienza con cantidades moderadas","No combinar con somníferos recetados"]', 'Se recomienda evitar la valeriana durante el embarazo; opta por manzanilla y rutinas de relajación.', '["Insomnio severo por más de cuatro semanas","Ronquidos intensos o pausas respiratorias al dormir","Somnolencia diurna peligrosa"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('trouble-sleeping', 'pt-BR', 'Dificuldade para adormecer ou manter o sono', 'Restauração do ritmo de descanso com rituais noturnos simples, chás aromáticos e desaceleração.', '["Passiflora / Maracujá (Passiflora incarnata)","Valeriana (Valeriana officinalis)","Alimentos fontes de magnésio (sementes, castanhas)"]', '["Horário regular para acordar pela manhã","Redução de luzes e telas 60 minutos antes de se deitar","Ritual de chá morno e leitura leve"]', '["A valeriana pode provocar lentidão matinal em organismos sensíveis; use doses pequenas","Não misturar com medicamentos para dormir"]', 'Evite a valeriana na gestação; prefira camomila leve e práticas de respiração.', '["Insônia frequente há mais de um mês","Engasgos ou roncos fortes durante a noite","Cansaço excessivo que afete a segurança no trânsito"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('tension-headaches', 'en', 'Tension headaches and neck stiffness', 'Relieving everyday pressure from prolonged focus, dehydration, and shoulder bracing.', '["Peppermint essential oil (Mentha piperita, diluted topically on temples/neck)","Feverfew (Tanacetum parthenium)","Hydration with trace minerals"]', '["Drink 250–350 ml water immediately upon noticing early tightness","Five-minute neck rolls and shoulder shrugs","Ten minutes of outdoor natural light without screens"]', '["Always dilute peppermint oil in a carrier oil before skin application","Do not use feverfew if allergic to ragweed"]', 'Avoid feverfew during pregnancy. Use cold compresses, gentle shoulder stretches, and adequate hydration.', '["Sudden \"thunderclap\" headache of unprecedented severity","Headache accompanied by high fever, stiff neck, or confusion","Neurological signs: vision changes, weakness, or slurred speech"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('tension-headaches', 'es', 'Dolores de cabeza por tensión y rigidez', 'Alivio de la sobrecarga muscular por concentración continua, deshidratación y postura fija.', '["Menta piperita (aceite diluido en sienes y nuca)","Matricaria o santamaría (Tanacetum parthenium)","Agua fresca con electrolitos naturales"]', '["Beber un vaso de agua ante los primeros avisos de tensión","Movimientos suaves de hombros y cuello durante cinco minutos","Paseo breve a la luz del día sin mirar pantallas"]', '["Diluir siempre el aceite de menta en un aceite vegetal base","Evitar la matricaria si hay alergia a plantas compuestas"]', 'No utilizar matricaria en el embarazo. Emplear compresas frescas, descanso e hidratación adecuada.', '["Dolor de cabeza repentino y de intensidad extrema nunca antes sentida","Fiebre alta con rigidez de nuca","Alteraciones visuales, debilidad en extremidades o dificultad para hablar"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('tension-headaches', 'pt-BR', 'Dores de cabeça por tensão e rigidez no pescoço', 'Alívio para a sobrecarga física decorrente de esforço visual, postura e desidratação.', '["Óleo essencial de hortelã-pimenta (diluído na nuca e têmporas)","Tanaceto (Tanacetum parthenium)","Boa hidratação ao longo do dia"]', '["Beber um copo d’água aos primeiros sinais de incômodo","Movimentos circulares com os ombros por alguns minutos","Pausa de dez minutos ao ar livre sem telas"]', '["Sempre dilua o óleo essencial em óleo carreador antes de aplicar na pele","Atenção a pessoas com alergias botânicas"]', 'Evitar o tanaceto na gravidez. Priorize compressas mornas ou frias e descanso adequado.', '["Dor súbita e explosiva de intensidade incomum","Febre associada a rigidez na nuca","Visão turva, dormência ou fraqueza súbita"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('digestive-upset', 'en', 'Digestive upset, bloating, and nervous stomach', 'Gentle warming botanicals and unhurried meal rhythms for gut sensitivity and stress-related tension.', '["Ginger root (Zingiber officinale)","Fennel seed (Foeniculum vulgare)","Peppermint leaf (Mentha piperita)"]', '["Slow, unhurried eating without screens or distressing news","Warm ginger or fennel tea 20 minutes post-meal","Gentle 10–15 minute walk after eating to support natural peristalsis"]', '["Peppermint can aggravate gastroesophageal reflux (GERD) in some individuals by relaxing the lower esophageal sphincter"]', 'Moderate culinary ginger is widely used for nausea; avoid large medicinal doses without obstetrical guidance.', '["Unintended significant weight loss","Persistent severe abdominal pain or vomiting","Blood in stool or black tarry stools"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('digestive-upset', 'es', 'Malestar digestivo, pesadez e inflamación', 'Plantas tradicionales carminativas y ritmos tranquilos para acompañar la digestión y el estómago sensible.', '["Jengibre (Zingiber officinale)","Semillas de hinojo (Foeniculum vulgare)","Menta verde o piperita (Mentha piperita)"]', '["Comer despacio, masticando con calma y sin pantallas","Infusión tibia de jengibre o hinojo después de los alimentos","Paseo suave de diez minutos para favorecer la digestión"]', '["La menta puede aumentar el reflujo en personas con acidez estomacal"]', 'El jengibre suave es tradicional para náuseas matutinas; consultar con el médico antes de concentrados.', '["Pérdida de peso involuntaria","Dolor abdominal agudo o persistente","Presencia de sangre en heces o vómitos recurrentes"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('digestive-upset', 'pt-BR', 'Desconforto digestivo, estufamento e digestão lenta', 'Chás digestivos tradicionais e pausas conscientes para acalmar o estômago sob tensão.', '["Gengibre (Zingiber officinale)","Sementes de erva-doce / funcho (Foeniculum vulgare)","Hortelã (Mentha piperita)"]', '["Refeições sem pressa, longe de telas e discussões","Chá morno de funcho ou gengibre após as refeições","Caminhada leve de dez minutos para auxiliar o trânsito intestinal"]', '["A hortelã pode acentuar o refluxo em pessoas propensas a azia"]', 'O gengibre em doses culinárias é bem aceito para enjoo; evite extratos fortes sem orientação obstétrica.', '["Perda de peso sem causa aparente","Dor abdominal intensa e contínua","Sinais de sangramento digestivo"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('inflammation-achiness', 'en', 'Low-grade inflammation & systemic achiness', 'Nourishing the body through colorful whole foods, restorative sleep, and gentle circulatory movement.', '["Turmeric root (Curcuma longa) with black pepper","Tart cherry juice","Omega-3 rich foods (flaxseeds, walnuts)"]', '["Daily joint circles and unhurried stretching","Protecting a 7–8 hour sleep sanctuary","Alternating warm and cool compresses for joint ease"]', '["Turmeric in high therapeutic doses can thin blood; consult a physician if taking anticoagulants"]', 'Use turmeric freely as a culinary spice; avoid concentrated curcumin supplements during pregnancy.', '["Hot, swollen, red joints with fever","Morning stiffness lasting longer than an hour daily","Unexplained joint pain traveling between limbs"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('inflammation-achiness', 'es', 'Molestias articulares y sensación de pesadez corporal', 'Nutrición rica en antioxidantes, descanso nocturno reparador y movimiento suave para el cuerpo cansado.', '["Cúrcuma (Curcuma longa) con un toque de pimienta negra","Cerezas ácidas o frutos rojos","Semillas de lino y nueces ricas en omega-3"]', '["Movimientos circulares de articulaciones cada mañana","Cuidar una ventana de sueño de 7 a 8 horas","Compresas templadas en zonas con rigidez"]', '["Dosis elevadas de cúrcuma pueden interactuar con anticoagulantes; consultar con el médico"]', 'Consumir cúrcuma como condimento culinario; evitar suplementos concentrados en el embarazo.', '["Articulaciones inflamadas, calientes y enrojecidas","Rigidez matutina intensa que dure más de una hora","Dolor acompañado de fiebre"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('inflammation-achiness', 'pt-BR', 'Sensação de cansaço corporal e rigidez articular', 'Alimentação protetora, sono de qualidade e movimento gentil para desarmar o desconforto diário.', '["Cúrcuma / Açafrão-da-terra (Curcuma longa) com pimenta-do-reino","Frutas vermelhas","Sementes de linhaça e nozes"]', '["Alongamento suave ao acordar e rotação articular","Prioridade para uma noite de sono de 7 a 8 horas","Bolsa de água morna nos pontos de tensão"]', '["Extratos concentrados de cúrcuma exigem cautela em quem toma anticoagulantes"]', 'Seguro como tempero na comida; evitar cápsulas concentradas durante a gravidez.', '["Articulações visivelmente inchadas com calor e rubor","Rigidez matinal severa prolongada","Dores articulares associadas a febre"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('unexplained-fatigue', 'en', 'Fatigue without a clear cause', 'Approaching low energy as a whole-system invitation to rest, assess rhythms, and schedule essential medical screening.', '["Ashwagandha (Withania somnifera) — with clinician review","Rhodiola rosea","Nourishing broths"]', '["Morning outdoor sunlight exposure within 30 minutes of waking","Regular balanced meals avoiding sudden blood sugar spikes","Gentle screen-free wind-down ritual at twilight"]', '["Never assume prolonged exhaustion is simply \"burnout\" without basic clinical bloodwork (iron/ferritin, thyroid panel, vitamin D, and metabolic markers)"]', 'Adaptogenic herbs like ashwagandha and rhodiola are not recommended in pregnancy. Rely on restorative sleep and nutritious food.', '["Profound exhaustion that prevents leaving bed","Unexplained night sweats, swollen lymph nodes, or fever","Extreme daytime sleepiness indicating possible sleep apnea"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('unexplained-fatigue', 'es', 'Cansancio persistente sin causa aparente', 'Una mirada integral a la falta de energía: revisar ritmos de vida, nutrición y descartar causas clínicas.', '["Ashwagandha (Withania somnifera) — previa consulta profesional","Rodiola (Rhodiola rosea)","Caldos caseros de verduras"]', '["Exposición a la luz natural matutina en los primeros 30 minutos","Comidas a horarios fijos para estabilizar la energía","Pausa relajante al anochecer sin pantallas"]', '["No asumir que todo cansancio es estrés; es fundamental realizar análisis clínicos básicos (hierro, tiroides, vitamina D)"]', 'Evitar plantas adaptógenas en el embarazo. Priorizar el descanso y la alimentación equilibrada.', '["Fatiga extrema que impida levantarse de la cama","Sudores nocturnos, ganglios inflamados o fiebre inexplicable","Pausas en la respiración al dormir"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('unexplained-fatigue', 'pt-BR', 'Cansaço constante e falta de disposição', 'Acolhendo o cansaço como um sinal do corpo para revisar hábitos e realizar exames laboratoriais essenciais.', '["Ashwagandha (Withania somnifera) — com orientação profissional","Rhodiola rosea","Sopas e caldos nutritivos"]', '["Luz solar pela manhã logo após acordar","Alimentação equilibrada para evitar picos de glicemia","Desconexão de telas ao anoitecer"]', '["O cansaço crônico requer avaliação médica (ferritina, tireoide, vitamina D e hemograma)"]', 'Plantas adaptógenas devem ser evitadas na gestação. Valorize o repouso e a boa hidratação.', '["Exaustão que impeça os cuidados básicos do dia","Sudorese noturna ou febre sem motivo evidente","Sonolência excessiva durante o dia"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('low-mood-grief', 'en', 'Low mood, grief, and emotional flatness', 'Gentle companionship, light exposure, and contemplative care when joy feels distant.', '["St. John’s Wort (Hypericum perforatum) — CAUTION: extensive drug interactions","Holy Basil / Tulsi (Ocimum sanctum)","Chamomile and lavender infusions"]', '["Twenty minutes of unhurried outdoor walking in natural daylight","Gentle loving-kindness reflection for yourself and one supportive person","Honoring grief with the continuing bond practice"]', '["St. John’s Wort interacts dangerously with antidepressants (SSRIs/SNRIs), birth control pills, and blood thinners; always speak with a pharmacist first"]', 'Avoid St. John’s Wort during pregnancy. Prioritize counseling, gentle walks, and community connection.', '["Thoughts of suicide or self-harm (Call or text 988 immediately)","Persistent feelings of total hopelessness lasting over two weeks","Inability to care for basic personal hygiene or eat"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('low-mood-grief', 'es', 'Desánimo, tristeza profunda y desgana', 'Acompañamiento respetuoso, luz natural y prácticas de afecto cuando el ánimo decae.', '["Hierba de San Juan (Hypericum perforatum) — ATENCIÓN: múltiples interacciones farmacológicas","Albahaca sagrada o Tulsi (Ocimum sanctum)","Infusión reconfortante de manzanilla"]', '["Caminar veinte minutos bajo la luz del sol","Práctica de compasión y ternura hacia uno mismo","Espacio contenido para dar voz a la tristeza"]', '["La hierba de San Juan interactúa con antidepresivos, anticonceptivos y anticoagulantes; consultar siempre a un profesional"]', 'No usar hierba de San Juan en el embarazo. Apóyate en personas de confianza y acompañamiento profesional.', '["Pensamientos de autolesión o suicidio (Comunícate de inmediato con el 988 o servicios de emergencia)","Tristeza inmovilizante por más de dos semanas","Dificultad severa para alimentarse o levantarse"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('low-mood-grief', 'pt-BR', 'Desânimo, tristeza e sensação de vazio', 'Presença acolhedora, contato com a natureza e práticas de carinho quando o coração está pesado.', '["Erva-de-são-joão (Hypericum perforatum) — ATENÇÃO: fortes interações medicamentosas","Manjericão-sagrado / Tulsi (Ocimum sanctum)","Infusão de camomila e erva-doce"]', '["Caminhada de vinte minutos à luz do dia","Prática da gentileza consigo mesmo em três passos","Momento de acolhimento para o que você está sentindo"]', '["A erva-de-são-joão altera a eficácia de antidepressivos, anticoncepcionais e outros remédios"]', 'Evitar erva-de-são-joão na gravidez. Busque apoio em profissionais de saúde mental e pessoas queridas.', '["Pensamentos de machucar a si mesmo (Ligue ou envie mensagem ao 988 ou serviços de crise)","Sensação paralisante de desesperança contínua","Incapacidade de realizar cuidados essenciais"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('stress-overwhelm', 'en', 'Stress, sensory overload, and burnout', 'Creating intentional pauses, setting clean interpersonal limits, and resetting an over-stimulated nervous system.', '["Lemon Balm tea (Melissa officinalis)","Milky Oat Tops (Avena sativa)","Epsom salt warm baths"]', '["Sigh breathing: two quick inhales through the nose, long audible exhale through the mouth","Setting one clear boundary sentence today","15-minute nature immersion without phone"]', '["Stress manifests somatically; do not ignore new physical symptoms as \"just stress\" without clinical check"]', 'Gentle herbal teas like lemon balm and oat straw are safe culinary choices; avoid extreme hot baths.', '["Severe panic attacks with disorientation","Chest pain or irregular heart palpitations","Complete emotional detachment or depersonalization"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('stress-overwhelm', 'es', 'Estrés continuo y sobrecarga sensorial', 'Espacios de silencio, límites sanos y respiración calmante para aliviar la sobreestimulación.', '["Toronjil o melisa (Melissa officinalis)","Avena verde (Avena sativa)","Baños tibios con sales minerales"]', '["Suspiro fisiológico: doble inhalación corta por la nariz y exhalación larga y suave por la boca","Decir un \"no\" sereno a un compromiso no esencial","Quince minutos en un parque o jardín sin teléfono"]', '["No descartar síntomas físicos nuevos sin una revisión médica adecuada"]', 'Infusiones suaves de melisa son bien toleradas; evitar baños de agua excesivamente caliente.', '["Crisis de angustia con confusión","Dolor u opresión en el pecho","Desconexión emocional severa"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('stress-overwhelm', 'pt-BR', 'Sobrecarga de estímulos e estresse contínuo', 'Pausas conscientes, limites claros nas relações e respiração relaxante para acalmar os sentidos.', '["Erva-cidreira (Melissa officinalis)","Aveia em infusão suave (Avena sativa)","Escalda-pés com água morna e sais"]', '["Suspiro fisiológico: duas inspirações curtas pelo nariz e uma expiração longa e solta pela boca","Praticar um limite claro sem se justificar demais","Pausa ao ar livre em contato com plantas sem celular"]', '["Sintomas corporais novos merecem avaliação médica preventiva"]', 'Chá de erva-cidreira em doses leves é seguro; evite banhos de imersão muito quentes.', '["Crises frequentes de falta de ar e taquicardia","Dor torácica persistente","Sensação de perda de contato com a realidade"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('common-colds', 'en', 'Common colds and seasonal sniffles', 'Supporting the body’s innate immune response with hydration, botanical warmth, and restful recuperation.', '["Elderberry syrup (Sambucus nigra)","Fresh Ginger & Honey infusion","Echinacea (Echinacea purpurea)"]', '["Warm saline nasal rinses with distilled water","Prioritizing extra sleep: 9–10 hours during acute symptoms","Warm steam inhalation with a drop of thyme or eucalyptus oil"]', '["Herbal supports do not replace medical treatment, antiviral therapy, or vaccines","Always use distilled or boiled water for nasal irrigation"]', 'Elderberry syrup in standard culinary amounts is generally well tolerated; consult your prenatal provider regarding echinacea.', '["Difficulty breathing, wheezing, or chest pain","High fever lasting more than 72 hours","Symptoms that significantly worsen after initial improvement"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('common-colds', 'es', 'Resfriados comunes y molestias de estación', 'Apoyar las defensas naturales del cuerpo mediante descanso, hidratación y calor botánico.', '["Jarabe suave de saúco (Sambucus nigra)","Infusión de jengibre fresco con limón y miel","Equinácea (Echinacea purpurea)"]', '["Lavados nasales con solución salina estéril","Aumentar las horas de descanso nocturno","Vahos de vapor tibio para despejar las vías respiratorias"]', '["Las plantas no reemplazan vacunas ni tratamientos médicos necesarios","Usar siempre agua hervida o destilada para lavados nasales"]', 'Consumir miel con limón y caldos tibios; consultar sobre el uso de equinácea durante el embarazo.', '["Dificultad para respirar o silbidos en el pecho","Fiebre alta por más de tres días consecutivos","Recaída brusca tras una mejoría inicial"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('common-colds', 'pt-BR', 'Resfriados e indisposição de mudança de tempo', 'Apoio ao sistema imunológico com repouso, hidratação abundante e chás reconfortantes.', '["Xarope de sabugueiro (Sambucus nigra)","Chá de gengibre fresco com limão e mel","Equinácea (Echinacea purpurea)"]', '["Lavagem nasal com soro fisiológico estéril","Dormir mais cedo para dar tempo ao corpo de se recuperar","Inalação de vapor morno para aliviar a congestão"]', '["Cuidados naturais não substituem vacinas nem antibióticos quando necessários","Higienizar bem os recipientes de lavagem nasal"]', 'Hidratação e chás leves são ideais; confirme com seu obstetra o uso de equinácea.', '["Falta de ar ou dor ao respirar fundo","Febre alta persistente por mais de 72 horas","Piora repentina dos sintomas"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('menstrual-discomfort', 'en', 'Menstrual discomfort and pelvic tension', 'Warmth, pelvic easing movements, and antispasmodic herbs for monthly cycle tenderness.', '["Cramp Bark (Viburnum opulus)","Ginger root (Zingiber officinale)","Raspberry Leaf (Rubus idaeus)"]', '["Warm hot water bottle or heating pad over lower abdomen and lower back","Gentle restorative child’s pose or supported pelvic butterfly stretch","Cycle journaling to identify patterns in rest and energy"]', '["Raspberry leaf is traditionally avoided in early pregnancy unless guided by a midwife"]', 'Menstrual remedies do not apply in pregnancy; any acute pelvic pain or bleeding requires immediate obstetrical care.', '["Sudden, agonizing pelvic pain not relieved by heat or rest","Excessively heavy bleeding (soaking more than two pads an hour for consecutive hours)","Severe fever accompanying pelvic tenderness"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('menstrual-discomfort', 'es', 'Molestias menstruales y tensión pélvica', 'Calor reconfortante, posturas suaves y plantas antiespasmódicas para los días del ciclo.', '["Corteza de viburno o cramp bark (Viburnum opulus)","Jengibre (Zingiber officinale)","Hojas de frambueso (Rubus idaeus)"]', '["Compresa tibia en el bajo vientre y zona lumbar","Postura suave de descanso con cojines bajo las rodillas","Llevar un diario del ciclo para sincronizar el ritmo de trabajo"]', '["Evitar infusiones de frambueso en el primer trimestre de embarazo sin indicación"]', 'Cualquier dolor pélvico agudo o sangrado en el embarazo debe ser revisado de inmediato.', '["Dolor pélvico repentino e insoportable","Sangrado muy abundante que empape compresas en lapsos cortos","Fiebre acompañada de dolor pélvico"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('menstrual-discomfort', 'pt-BR', 'Cólicas menstruais e desconforto pélvico', 'Calor local, movimentos suaves de alívio e chás para os dias mais sensíveis do ciclo.', '["Viburno / Cramp bark (Viburnum opulus)","Gengibre (Zingiber officinale)","Folhas de framboeseira (Rubus idaeus)"]', '["Bolsa de água quente sobre o abdômen e na lombar","Postura de descanso com almofadas apoiando o corpo","Anotar as fases do ciclo para desacelerar nos dias necessários"]', '["Chá de folha de framboesa deve ser evitado no início da gravidez sem orientação"]', 'Dores pélvicas ou sangramento na gestação requerem atendimento médico imediato.', '["Dor intensa e súbita que não cede com calor ou repouso","Fluxo excessivamente hemorrágico","Febre associada a cólicas agudas"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('skin-sensitivity', 'en', 'Skin irritation, dryness, and sensitivity', 'Simplifying topical routines, honoring skin barrier integrity, and applying soothing botanical compresses.', '["Calendula flower (Calendula officinalis)","Colloidal oatmeal baths","Pure Aloe Vera inner leaf gel"]', '["Lukewarm short showers instead of steaming hot water","Fragrance-free, minimal-ingredient moisturizers applied to damp skin","Soft cotton clothing without irritating synthetic tags"]', '["Always patch-test any new botanical oil on the inside of the wrist for 24 hours before broader use"]', 'Calendula and oatmeal are exceptionally gentle and safe for external use across all life stages.', '["Spreading redness with warmth and throbbing pain (possible cellulitis)","Blistering accompanied by fever","Hives spreading rapidly with any facial swelling or throat tightness (call 911)"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('skin-sensitivity', 'es', 'Sensibilidad en la piel, sequedad e irritación', 'Simplificar el cuidado diario, proteger la barrera cutánea y utilizar compresas botánicas suaves.', '["Caléndula (Calendula officinalis)","Baños con harina fina de avena coloidal","Gel puro de sábila / aloe vera"]', '["Duchas con agua tibia en lugar de caliente","Hidratación con cremas neutras y sin perfumes tras el baño","Ropa de algodón suave que no cause fricción"]', '["Realizar una prueba en la muñeca antes de aplicar productos botánicos nuevos"]', 'La caléndula y la avena son sumamente nobles y seguras para uso tópico.', '["Enrojecimiento que se expande con calor y dolor punzante","Ampollas acompañadas de fiebre","Urticaria súbita con hinchazón en labios o garganta (urgencia médica)"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('skin-sensitivity', 'pt-BR', 'Pele sensível, ressecamento e irritações leves', 'Rotina simplificada de cuidados, respeito à barreira cutânea e compressas calmantes.', '["Calêndula (Calendula officinalis)","Aveia coloidal para banhos suaves","Babosa / Aloe vera pura"]', '["Banhos mornos e rápidos sem sabonetes agressivos","Hidratante sem fragrância aplicado com a pele ainda úmida","Peças de algodão confortáveis"]', '["Faça um teste de contato no antebraço antes de usar novos extratos na pele"]', 'Calêndula e aveia são opções tópicas muito seguras e suaves para todas as idades.', '["Área vermelha que se espalha com calor e dor (suspeita de infecção bacteriana)","Bolhas dolorosas com febre","Inchaço repentino no rosto ou dificuldade para engolir (emergência)"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('desk-aches', 'en', 'Everyday aches from screen, desk, and phone', 'Micro-movements, eye-rest breaks, and gentle somatic releases to break the habit of static posture.', '["Warm Arnica massage oil (Arnica montana — unbroken skin only)","Hydration with electrolytes","Topical magnesium lotion"]', '["The 20-20-20 rule: every 20 minutes, look at an object 20 feet away for 20 seconds","Hourly 30-second chest-opening stretch and neck roll","Setting top of screen at natural eye level to prevent forward head tilt"]', '["Never apply arnica to broken skin or open cuts"]', 'Topical arnica in modest amounts is safe; maintain ergonomic support with pregnancy pillows.', '["Radiating numbness, tingling, or electrical pain down an arm or leg","Sudden weakness in hands (dropping objects involuntarily)","Severe spinal pain following a fall or injury"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('desk-aches', 'es', 'Sobrecarga física por pantallas y trabajo de escritorio', 'Micromovimientos, pausas visuales y estiramientos suaves para compensar la postura sedentaria.', '["Aceite de árnica para masaje (Arnica montana — solo en piel sana)","Buena hidratación diaria","Loción suave con magnesio"]', '["Regla 20-20-20: cada 20 minutos, mira a lo lejos por 20 segundos para descansar la vista","Pausas breves para abrir el pecho y rotar los hombros","Ajustar la pantalla a la altura de los ojos para cuidar el cuello"]', '["No aplicar árnica sobre rasguños o heridas abiertas"]', 'El árnica tópica suave es segura; acompañar con cojines de apoyo para la espalda.', '["Hormigueo continuo o sensación eléctrica que baja por los brazos o piernas","Pérdida de fuerza en las manos","Dolor agudo en la columna"]');
INSERT OR REPLACE INTO remedy_translations (remedy_id, locale, title, summary, botanical_allies, somatic_approaches, cautions, pregnancy_warning, escalation_flags) VALUES ('desk-aches', 'pt-BR', 'Tensões cotidianas do computador e do celular', 'Micromovimentos, descanso para os olhos e alongamentos para desfazer a rigidez postural.', '["Óleo vegetal com arnica para massagem (Arnica montana — apenas na pele íntegra)","Hidratação constante","Creme com magnésio para relaxamento"]', '["Pausa 20-20-20: a cada 20 minutos, olhe para longe por 20 segundos para descansar a visão","Alongamento rápido de peito e pescoço a cada hora","Posicionar a tela na altura dos olhos para evitar sobrecarga cervical"]', '["Nunca passe arnica em ferimentos ou pele machucada"]', 'O uso tópico leve de arnica é tranquilo; use almofadas para apoiar a postura.', '["Formigamento constante ou choques descendo pelos braços ou pernas","Perda de força ao segurar objetos","Dor forte na coluna após impacto"]');

-- Table: reiki_articles (6 rows)
INSERT OR REPLACE INTO reiki_articles (id, slug, locale, title, summary, content, sort_order, created_at) VALUES ('reiki-foundations_en', 'understanding-reiki-traditions', 'en', 'Understanding Reiki: History, Presence, and Quiet Care', 'An honest look at what Reiki is, its roots with Mikao Usui, and how gentle presence supports wellness.', '### What Reiki is and how it began

Reiki is a Japanese tradition of spiritual and meditative healing founded by Mikao Usui in Japan in the early 1920s. The word itself brings together *rei* (sacred, subtle, or spiritual) and *ki* (vital life energy).

At its core, Reiki is not a medical procedure or a pharmaceutical intervention. It is an art of quiet presence, respectful touch or near-body placement, and mindful centering. Through deep personal grounding and clear ethical boundaries, the practitioner offers a steady, calm, and supportive space where the recipient''s nervous system can shift into deep relaxation.

### The five principles of Usui Reiki (Gokai)

1. Just for today, do not be angry.
2. Just for today, do not worry.
3. Be filled with gratitude.
4. Devote yourself to your work.
5. Be kind to all people.

### What to expect in a session

You remain fully clothed, resting comfortably on a massage table or seated in a quiet chair. The practitioner places their hands gently on or slightly above traditional energy centers. Many report feeling gentle warmth or simply a profound sense of deep, peaceful rest.

### Ethical and medical boundaries

Reiki is an educational and complementary practice; it is never a substitute for medical evaluation, psychiatric care, or prescription medications.', 1, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO reiki_articles (id, slug, locale, title, summary, content, sort_order, created_at) VALUES ('reiki-foundations_es', 'understanding-reiki-traditions', 'es', 'Comprender el Reiki: Tradición, presencia y serenidad', 'Una mirada sincera sobre el Reiki, sus orígenes con Mikao Usui y el valor del acompañamiento respetuoso.', '### Qué es el Reiki y sus orígenes

El Reiki es una tradición de origen japonés desarrollada a comienzos de la década de 1920 por Mikao Usui. Su nombre une dos ideas: *rei* (lo sutil, sagrado o universal) y *ki* (la energía vital que sostiene la vida).

Lejos de promesas milagrosas, el Reiki tradicional es una práctica meditativa y de acompañamiento. A través del silencio, la respiración y la imposición suave de manos, el practicante brinda un entorno seguro donde la persona puede descansar profundamente y permitir que su sistema nervioso recupere el equilibrio.

### Los cinco principios cotidianos (Gokai)

1. Solo por hoy, no te enojes.
2. Solo por hoy, no te preocupes.
3. Vive con gratitud.
4. Trabaja con dedicación y honestidad.
5. Sé amable con los demás.

### Límites claros y éticos

El Reiki en KindWell es un complemento de bienestar y reflexión espiritual. No sustituye la atención médica ni psicológica, no emite diagnósticos ni modifica tratamientos prescritos por profesionales de la salud.', 1, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO reiki_articles (id, slug, locale, title, summary, content, sort_order, created_at) VALUES ('reiki-foundations_pt-BR', 'understanding-reiki-traditions', 'pt-BR', 'Compreendendo o Reiki: História, presença e acolhimento', 'Uma reflexão honesta sobre o Reiki, suas raízes com Mikao Usui e o descanso profundo que ele proporciona.', '### O que é o Reiki e como nasceu essa tradição

O Reiki é uma prática contemplativa de origem japonesa sistematizada por Mikao Usui no início do século XX. O termo reúne *rei* (dimensão espiritual e sutil) e *ki* (energia vital que permeia a existência).

Não se trata de um procedimento médico, mas de uma prática de presença consciente e toque suave. O objetivo é criar um espaço sereno onde o corpo e a mente possam desacelerar, ativando as respostas naturais de relaxamento e recuperação.

### Os cinco princípios diários (Gokai)

1. Só por hoje, não se zangue.
2. Só por hoje, não se preocupe.
3. Seja grato.
4. Dedique-se com integridade ao seu dia.
5. Seja gentil com todos.

### Ética e responsabilidade

O Reiki é uma ferramenta de suporte integrativo e bem-estar. Jamais substitui consultas médicas, tratamentos psiquiátricos ou terapias necessárias para a saúde física e mental.', 1, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO reiki_articles (id, slug, locale, title, summary, content, sort_order, created_at) VALUES ('reiki-self-practice_en', 'reiki-self-practice-and-meditation', 'en', 'Self-Practice & Daily Contemplation', 'How to bring gentle touch, mindful breath, and compassionate stillness into your own daily life.', '### The gift of self-treatment

One of the most practical and grounding aspects of traditional Reiki is self-practice (*Jiko Joka Ho*). You do not need professional certification to place your own warm hands over your chest, breathe with quiet intention, and offer yourself unconditional acceptance.

### A simple 10-minute self-practice ritual

1. **Gassho (Centering):** Bring your palms together at heart level. Take three steady breaths.
2. **Head & Temples:** Rest your palms gently over your closed eyes or at the temples.
3. **Heart & Solar Center:** Place one hand on your heart and one on your upper belly.
4. **Closing Gratitude:** Return hands to prayer position, acknowledging the quiet stillness you cultivated.', 2, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO reiki_articles (id, slug, locale, title, summary, content, sort_order, created_at) VALUES ('reiki-self-practice_es', 'reiki-self-practice-and-meditation', 'es', 'Práctica personal y meditación cotidiana', 'Cómo integrar el tacto suave, la respiración atenta y la calma en tu propia rutina diaria.', '### El valor de cuidarse a uno mismo

El aspecto más accesible del Reiki es la autopráctica. No necesitas títulos para apoyar tus propias manos sobre el pecho, respirar con cariño y regalarte unos minutos de silencio.

### Ritual de diez minutos para el hogar

1. **Centramiento:** Junta las palmas a la altura del corazón y respira tres veces con tranquilidad.
2. **Ojos y rostro:** Apoya suavemente las manos sobre los ojos o la frente.
3. **Pecho y abdomen:** Coloca una mano en el corazón y otra en el vientre.
4. **Cierre:** Da las gracias por este instante de quietud y regresa a tus actividades con serenidad.', 2, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO reiki_articles (id, slug, locale, title, summary, content, sort_order, created_at) VALUES ('reiki-self-practice_pt-BR', 'reiki-self-practice-and-meditation', 'pt-BR', 'Autocuidado e meditação diária', 'Como incorporar o toque suave, a respiração consciente e a paz à sua própria rotina.', '### O valor do autocuidado na prática pessoal

A essência mais bonita do Reiki está na possibilidade de cuidar de si. Você pode descansar as próprias mãos sobre o peito e respirar com afeto sem precisar de nenhuma técnica complicada.

### Um ritual simples de 10 minutos

1. **Centralização:** Junte as mãos diante do coração e faça três respirações calmas.
2. **Rosto e têmporas:** Acomode as palmas suavemente sobre os olhos.
3. **Peito e respiração:** Uma mão no peito e outra no abdômen, acompanhando o ritmo do corpo.
4. **Finalização:** Agradeça pelo momento de pausa e retome o dia com mais leveza.', 2, '2026-09-23T10:40:44.471Z');

-- Table: crystals (24 rows)
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('amethyst', 'amethyst', 'Amethyst', 'en', 'Contemplation, quiet clarity, spiritual stillness', 'Used since antiquity across Mediterranean and Asian traditions to encourage clear-minded reflection and restful sleep.', 'Purple to deep violet quartz crystal, often showing natural geometric points and gentle color banding.', 'Rinse with clean water; keep out of prolonged direct sunlight to prevent natural color fading.', '7.0', 'Hold the cool stone in your palm when feeling mentally scattered; let its deep purple hue remind you of steady, unhurried presence.', 'Non-toxic, safe for everyday handling and water contact. Do not pulverize or inhale crystal dust.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('amethyst', 'amethyst', 'Amatista', 'es', 'Serenidad, contemplación y silencio interior', 'Apreciada desde la antigüedad para favorecer el descanso nocturno y la claridad mental durante la oración o la meditación.', 'Cuarzo de color violeta a púrpura profundo, con facetas cristalinas naturales y tonalidades cambiantes.', 'Se puede limpiar con agua fresca; conviene protegerla de la luz solar directa prolongada para conservar su color.', '7.0', 'Sostén la piedra en la palma de la mano cuando haya inquietud mental, respirando al compás de su frescura.', 'Piedra segura y no tóxica para uso cotidiano. Evita inhalar polvo mineral si se trabaja artesanalmente.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('amethyst', 'amethyst', 'Ametista', 'pt-BR', 'Tranquilidade, serenidade e clareza mental', 'Utilizada historicamente em diversas culturas como símbolo de equilíbrio, sabedoria e apoio a um sono reparador.', 'Variedade de quartzo em tons que vão do lilás suave ao violeta profundo com formações geométricas.', 'Pode ser lavada em água corrente; evite deixá-la sob sol forte constante para não desbotar.', '7.0', 'Apoie a pedra nas mãos durante uma pausa de respiração, deixando que sua cor profunda inspire calma.', 'Mineral seguro para manuseio diário. Não ingerir e evitar inalação de pó em caso de quebra.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('rose-quartz', 'rose-quartz', 'Rose Quartz', 'en', 'Gentleness, self-compassion, heartfelt kindness', 'Cherished as a symbolic talisman of emotional warmth, reconciliation, and kindness toward oneself and others.', 'Soft translucent pink mineral with cloudy interior veining and a smooth, gentle luster.', 'Clean with warm water and a soft cloth. Avoid harsh chemical cleaners.', '7.0', 'Place rose quartz over your heart center while practicing the three-part kindness pause.', 'Completely safe for skin contact and water. Not for preparing ingestible elixirs.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('rose-quartz', 'rose-quartz', 'Cuarzo rosa', 'es', 'Ternura, autocompasión y afecto sincero', 'Símbolo tradicional de reconciliación y amor bondadoso hacia uno mismo y hacia los demás.', 'Mineral de tonalidad rosada suave y traslúcida, con vetas internas acogedoras.', 'Lavar con agua templada y paño suave. No exponer a productos químicos abrasivos.', '7.0', 'Coloca el cuarzo rosa sobre el pecho mientras realizas la pausa de amabilidad personal.', 'Seguro para el tacto y el agua. No utilizar para preparar aguas o elixires ingeribles.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('rose-quartz', 'rose-quartz', 'Quartzo rosa', 'pt-BR', 'Gentileza, acolhimento e autocompaixão', 'Reconhecido como símbolo de afeto verdadeiro, paz nas relações e respeito pelos próprios sentimentos.', 'Cristal de cor rosa suave, translúcido e com aspecto delicado.', 'Limpar com água e pano macio. Evitar solventes ou produtos corrosivos.', '7.0', 'Mantenha o cristal próximo ao coração enquanto pratica pensamentos de apreço por si mesmo.', 'Mineral seguro para manuseio. Não indicado para infusões ou ingestão direta.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('black-tourmaline', 'black-tourmaline', 'Black Tourmaline (Schorl)', 'en', 'Grounding, firm boundaries, container of safety', 'Known across mineralogical and folklore traditions as a heavy anchor stone for grounding excess mental energy.', 'Opaque deep black with vertical striations, ridged texture, and natural mineral fractures.', 'Wipe with a damp cloth; dry thoroughly. Avoid soaking in water for extended periods due to natural micro-fissures.', '7.0 - 7.5', 'Hold when setting clear interpersonal boundaries or stepping out of overwhelming public environments.', 'Safe to handle. Brittle along natural cleavage planes; handle with care to avoid chipping.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('black-tourmaline', 'black-tourmaline', 'Turmalina negra (Chorlo)', 'es', 'Enraizamiento, límites saludables y firmeza', 'Piedra de referencia en el folclore mineral para anclar la energía y mantener el orden personal ante el ruido externo.', 'Negro opaco y brillante con estrías verticales y textura acanalada característica.', 'Limpiar con un paño ligeramente húmedo y secar de inmediato. No dejar sumergida por tiempo prolongado.', '7.0 - 7.5', 'Sostenla al momento de definir un límite saludable en el trabajo o la familia.', 'Segura para uso externo. Puede ser quebradiza si recibe golpes fuertes.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('black-tourmaline', 'black-tourmaline', 'Turmalina negra (Schorl)', 'pt-BR', 'Aterramento, firmeza e limites conscientes', 'Tradicionalmente associada à sensação de proteção, estrutura pessoal e pés no chão.', 'Preta brilhante e opaca com estrias longitudinais naturais bem definidas.', 'Limpar com pano macio umedecido e secar bem. Evitar imersão longa em água.', '7.0 - 7.5', 'Segure a turmalina ao praticar dizer um "não" consciente e cuidar do seu tempo.', 'Segura para manuseio diário. Manusear com cuidado para não quebrar as bordas.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('selenite', 'selenite', 'Selenite (Gypsum)', 'en', 'Quiet stillness, space clearing, mental purification', 'Named after Selene, ancient Greek goddess of the moon; long utilized in contemplative traditions as a visual focus for gentle quietness.', 'Pearly white fibrous mineral with a glowing, satiny, moon-like luminescence.', 'DO NOT SOAK IN WATER. Selenite is a soft gypsum mineral and will degrade or dissolve in water. Clean with a dry, soft cloth.', '2.0', 'Keep a selenite wand or bowl on your nightstand to mark the boundary between busy daytime activity and nighttime stillness.', 'Very soft (Mohs 2). Avoid scratching, dropping, or moisture exposure. Never ingest.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('selenite', 'selenite', 'Selenita (Yeso fibroso)', 'es', 'Silencio límpido, claridad mental y recogimiento', 'Su nombre evoca a Selene, la diosa lunar griega; apreciada como recordatorio de la paz y la sencillez en el hogar.', 'Mineral blanco lechoso y fibroso con un brillo sedoso semejante a la luz de la luna.', 'NO SUMERGIR EN AGUA. La selenita es yeso mineral y se deteriora o disuelve con el agua. Limpiar en seco con paño suave.', '2.0', 'Coloca una pieza de selenita en tu mesa de noche para señalar el final de la jornada y el inicio del descanso.', 'Piedra muy delicada (Mohs 2). Proteger de golpes y humedad. No apta para consumo.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('selenite', 'selenite', 'Selenita (Gipsita)', 'pt-BR', 'Serenidade pura, clareza e purificação do ambiente', 'Associada à deusa grega da lua, Selene; muito querida como símbolo de paz interior e desaceleração mental.', 'Mineral branco fibroso com brilho acetinado e suave translucidência.', 'NÃO MOLHAR. A selenita é um mineral solúvel em água e se desgasta facilmente. Limpar sempre a seco.', '2.0', 'Deixe uma selenita na cabeceira da cama para marcar o momento de recolhimento da noite.', 'Mineral muito macio e sensível (Mohs 2). Evitar quedas e umidade. Não ingerir.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('clear-quartz', 'clear-quartz', 'Clear Quartz', 'en', 'Intention, transparency, focused presence', 'Revered across every continent for millennia as the quintessential "light stone," used for holding focused prayers and intentions.', 'Prismatic, glass-clear to frosty white six-sided crystalline points with natural growth lines.', 'Extremely durable. Can be safely washed with cool water and mild soap.', '7.0', 'Hold in morning sunlight while quietly naming your primary intention or virtue for the day.', 'Completely non-toxic and physically robust. Handle natural points gently.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('clear-quartz', 'clear-quartz', 'Cuarzo cristal o cristal de roca', 'es', 'Claridad de intención, presencia y luminosidad', 'Venerado en diversas culturas como símbolo de transparencia y pureza, empleado para enfocar la oración y los buenos propósitos.', 'Cristales prismáticos transparentes con facetas limpias y destellos naturales.', 'Mineral muy resistente. Puede lavarse con agua templada y jabón suave.', '7.0', 'Sostenlo a la luz del amanecer mientras nombras en silencio tu intención para el día.', 'Completamente seguro y no tóxico para uso cotidiano.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('clear-quartz', 'clear-quartz', 'Quartzo cristal / Cristal de rocha', 'pt-BR', 'Transparência, foco e intenção pura', 'Apreciado historicamente como símbolo de luz e clareza, utilizado para apoiar orações e momentos de contemplação.', 'Cristal transparente e brilhante, com facetas geométricas bem definidas.', 'Muito resistente e durável. Pode ser lavado com água corrente e sabão neutro.', '7.0', 'Segure o cristal no início do dia e reflita sobre o propósito que você deseja cultivar hoje.', 'Mineral seguro e estável para manuseio diário.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('lepidolite', 'lepidolite', 'Lepidolite (Lithium Mica)', 'en', 'Gentle transitions, soothing overactive thoughts, emotional balance', 'A lilac-gray or rose-colored member of the mica family naturally rich in lithium, traditionally associated with easing life transitions.', 'Soft lavender to pinkish-grey tabular plates or sparkling granular masses with pearly luster.', 'Soft and flaky due to mica structure. Clean with a very gentle dry brush. DO NOT soak in water or use for drinking elixirs.', '2.5 - 3.0', 'Keep near your journal when processing difficult grief, major relocations, or career changes.', 'Contains naturally bound lithium and aluminum. Safe for skin handling. Never ingest, crush, or prepare water infusions.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('lepidolite', 'lepidolite', 'Lepidolita (Mica de litio)', 'es', 'Transiciones suaves, calma mental y sosiego en los cambios', 'Variedad de mica en tonos lilas rica en litio mineral, empleada simbólicamente para amortiguar los momentos de cambio brusco.', 'Mineral en tonos lila a rosáceo con brillo perlado y láminas cristalinas brillantes.', 'Estructura hojosa y frágil. Limpiar suavemente con un cepillo seco. NO dejar en agua ni preparar elixires.', '2.5 - 3.0', 'Acompáñate de esta piedra cuando escribas sobre cambios de vida o duelos recientes.', 'Contiene litio mineral de forma natural. Segura para sostener en las manos; nunca ingerir ni triturar.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('lepidolite', 'lepidolite', 'Lepidolita (Mica com lítio)', 'pt-BR', 'Paz nas transições, equilíbrio emocional e alívio de pensamentos agitados', 'Mineral da família das micas com tom lilás característico, conhecido na sabedoria popular por apoiar fases de mudança.', 'Coloração lilás ou rosada com lâminas brilhantes e textura perolada.', 'Mineral delicado e quebradiço. Limpar com pincel seco macio. NUNCA colocar na água para beber.', '2.5 - 3.0', 'Mantenha por perto enquanto faz anotações sobre decisões importantes ou mudanças na sua rotina.', 'Segura para manuseio externo. Nunca pulverizar nem ingerir.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('smoky-quartz', 'smoky-quartz', 'Smoky Quartz', 'en', 'Rootedness, emotional container, transforming heaviness into stability', 'The national gem of Scotland, traditionally carried in brooch pins and talismans to provide rooted stability in turbulent times.', 'Translucent brownish-gray to deep smoky black quartz with warm golden-amber highlights.', 'Durable and hard. Wash safely with water and mild soap.', '7.0', 'Hold in both palms while seated with feet firmly planted on the earth, allowing mental static to drain downward.', 'Completely safe, durable, and non-toxic.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('smoky-quartz', 'smoky-quartz', 'Cuarzo ahumado', 'es', 'Enraizamiento, contenedor emocional y firmeza', 'Gema tradicional en las tierras altas escocesas, utilizada históricamente como amuleto de estabilidad en épocas de incertidumbre.', 'Cuarzo traslúcido de color café grisáceo a pardo ahumado con reflejos dorados profundos.', 'Muy resistente. Se limpia fácilmente con agua y jabón neutro.', '7.0', 'Sostenlo sentado con los pies firmes en el suelo para invitar al cuerpo a soltar la sobrecarga.', 'Completamente seguro y duradero para uso continuo.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('smoky-quartz', 'smoky-quartz', 'Quartzo fumê', 'pt-BR', 'Pés no chão, estabilidade e acolhimento das emoções pesadas', 'Tradicionalmente usado como pedra de ancoragem, ajudando a dissipar o excesso de preocupação.', 'Quartzo translúcido em tonalidades que variam do cinza-acastanhado ao castanho escuro.', 'Mineral firme e resistente. Limpar com água corrente normalmente.', '7.0', 'Segure o cristal sentado confortavelmente, sentindo o apoio firme da terra sob seus pés.', 'Totalmente seguro e resistente para o dia a dia.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('fluorite', 'fluorite', 'Fluorite', 'en', 'Mental clarity, orderly thought, gentle discernment', 'Celebrated for its striking cubic crystal structures and vibrant color zoning, long considered an aid for focused study.', 'Banded translucent stone showing vivid greens, purples, blues, and clear zones in single specimens.', 'Moderate hardness (Mohs 4). Wipe with a soft damp cloth. Avoid harsh cleaners, acids, or hot water.', '4.0', 'Place on your study or work table to encourage calm, methodical discernment instead of hurried reactivity.', 'Safe to handle. Do not soak in drinking water or expose to acid.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('fluorite', 'fluorite', 'Fluorita', 'es', 'Claridad de ideas, orden mental y discernimiento tranquilo', 'Reconocida por sus fascinantes bandas de color y formaciones geométricas, valorada como apoyo para el estudio reflexivo.', 'Mineral traslúcido con franjas naturales en tonos verdes, violetas y azulados.', 'Dureza moderada (Mohs 4). Limpiar con paño húmedo suave. Evitar productos ácidos o agua muy caliente.', '4.0', 'Ubícala en tu mesa de lectura para inspirar orden y serenidad al organizar tus ideas.', 'Segura para el contacto manual. Evitar inmersiones en agua potable.');
INSERT OR REPLACE INTO crystals (id, slug, name, locale, spiritual_association, traditions, appearance, care_instructions, mohs_hardness, reflection_practice, safety_notes) VALUES ('fluorite', 'fluorite', 'Fluorita', 'pt-BR', 'Clareza de pensamento, foco sereno e discernimento', 'Famosa pelas belas faixas de cores e simetria natural, apreciada como companheira de estudos e leituras profundas.', 'Cristal translúcido com faixas naturais em verde, violeta e tons azulados.', 'Sensível a arranhões (Mohs 4). Limpar com pano macio levemente umedecido. Evitar ácidos.', '4.0', 'Deixe a fluorita na sua mesa de trabalho para lembrar de organizar uma tarefa por vez com calma.', 'Segura para manuseio. Não utilizar para preparar águas aromatizadas.');

-- Table: affirmations (90 rows)
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-18_en', '2026-09-18', 'en', 'You do not have to solve everything today.', 'Notice the weight of trying to figure out the next ten years in the next ten minutes. Put that down for a little while. Today only asks you to live today.', 'What is one question you can comfortably leave unanswered until tomorrow?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-18_es', '2026-09-18', 'es', 'No tienes que resolverlo todo el día de hoy.', 'Observa el cansancio de querer solucionar los próximos años en los próximos diez minutos. Suelta esa carga un momento; hoy solo te pide vivir el presente.', '¿Qué asunto pendiente puedes dejar descansar en paz hasta mañana?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-18_pt-BR', '2026-09-18', 'pt-BR', 'Você não precisa resolver tudo hoje.', 'Repare no peso de tentar solucionar o futuro inteiro nos próximos minutos. Coloque essa mala no chão por um instante. O dia de hoje pede apenas que você viva o agora.', 'Qual pergunta você pode deixar em aberto até amanhã com tranquilidade?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-19_en', '2026-09-19', 'en', 'Gentle doesn’t mean shallow.', 'Gentleness takes immense strength: the courage to pause, the wisdom to refrain from harsh words, and the patience to let healing unfold in its own time.', 'Where in your life would a little more gentleness actually create more resilience?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-19_es', '2026-09-19', 'es', 'La ternura no es debilidad.', 'Ser suave requiere gran valentía: la fortaleza de hacer una pausa, de evitar juicios duros y la paciencia de permitir que las cosas maduren a su ritmo.', '¿En qué situación de tu vida una mirada más comprensiva te daría mayor paz?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-19_pt-BR', '2026-09-19', 'pt-BR', 'A gentileza não é superficial.', 'Ser gentil exige uma coragem profunda: a firmeza de pausar, a sabedoria de não reagir com aspereza e a paciência com o próprio ritmo de crescimento.', 'Em qual parte da sua rotina um pouco mais de ternura traria mais serenidade?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-20_en', '2026-09-20', 'en', 'A steadier place to land.', 'When the world is loud and demanding, your breath is a quiet sanctuary that is always available to you right where you sit.', 'What physical anchor helps you feel supported when your thoughts feel scattered?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-20_es', '2026-09-20', 'es', 'Un lugar más firme donde aterrizar.', 'Cuando el entorno es ruidoso y exigente, tu respiración es un refugio discreto que siempre está disponible justo donde estás.', '¿Qué apoyo físico te ayuda a sentir estabilidad cuando la mente está dispersa?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-20_pt-BR', '2026-09-20', 'pt-BR', 'Um pouso mais sereno e seguro.', 'Quando o mundo ao redor parecer agitado demais, sua respiração é um refúgio simples e sempre presente no lugar onde você está.', 'Que detalhe ao seu redor ajuda a trazer firmeza quando a mente se perde em preocupações?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-21_en', '2026-09-21', 'en', 'You do not have to solve everything today.', 'Notice the weight of trying to figure out the next ten years in the next ten minutes. Put that down for a little while. Today only asks you to live today.', 'What is one question you can comfortably leave unanswered until tomorrow?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
