INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-23_es', '2026-09-23', 'es', 'Un lugar más firme donde aterrizar.', 'Cuando el entorno es ruidoso y exigente, tu respiración es un refugio discreto que siempre está disponible justo donde estás.', '¿Qué apoyo físico te ayuda a sentir estabilidad cuando la mente está dispersa?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
