INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-24_en', '2026-09-24', 'en', 'You do not have to solve everything today.', 'Notice the weight of trying to figure out the next ten years in the next ten minutes. Put that down for a little while. Today only asks you to live today.', 'What is one question you can comfortably leave unanswered until tomorrow?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-24_es', '2026-09-24', 'es', 'No tienes que resolverlo todo el día de hoy.', 'Observa el cansancio de querer solucionar los próximos años en los próximos diez minutos. Suelta esa carga un momento; hoy solo te pide vivir el presente.', '¿Qué asunto pendiente puedes dejar descansar en paz hasta mañana?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-24_pt-BR', '2026-09-24', 'pt-BR', 'Você não precisa resolver tudo hoje.', 'Repare no peso de tentar solucionar o futuro inteiro nos próximos minutos. Coloque essa mala no chão por um instante. O dia de hoje pede apenas que você viva o agora.', 'Qual pergunta você pode deixar em aberto até amanhã com tranquilidade?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-25_en', '2026-09-25', 'en', 'Gentle doesn’t mean shallow.', 'Gentleness takes immense strength: the courage to pause, the wisdom to refrain from harsh words, and the patience to let healing unfold in its own time.', 'Where in your life would a little more gentleness actually create more resilience?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-25_es', '2026-09-25', 'es', 'La ternura no es debilidad.', 'Ser suave requiere gran valentía: la fortaleza de hacer una pausa, de evitar juicios duros y la paciencia de permitir que las cosas maduren a su ritmo.', '¿En qué situación de tu vida una mirada más comprensiva te daría mayor paz?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-09-25_pt-BR', '2026-09-25', 'pt-BR', 'A gentileza não é superficial.', 'Ser gentil exige uma coragem profunda: a firmeza de pausar, a sabedoria de não reagir com aspereza e a paciência com o próprio ritmo de crescimento.', 'Em qual parte da sua rotina um pouco mais de ternura traria mais serenidade?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
