INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-10-09_pt-BR', '2026-10-09', 'pt-BR', 'Você não precisa resolver tudo hoje.', 'Repare no peso de tentar solucionar o futuro inteiro nos próximos minutos. Coloque essa mala no chão por um instante. O dia de hoje pede apenas que você viva o agora.', 'Qual pergunta você pode deixar em aberto até amanhã com tranquilidade?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-10-10_en', '2026-10-10', 'en', 'Gentle doesn’t mean shallow.', 'Gentleness takes immense strength: the courage to pause, the wisdom to refrain from harsh words, and the patience to let healing unfold in its own time.', 'Where in your life would a little more gentleness actually create more resilience?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-10-10_es', '2026-10-10', 'es', 'La ternura no es debilidad.', 'Ser suave requiere gran valentía: la fortaleza de hacer una pausa, de evitar juicios duros y la paciencia de permitir que las cosas maduren a su ritmo.', '¿En qué situación de tu vida una mirada más comprensiva te daría mayor paz?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-10-10_pt-BR', '2026-10-10', 'pt-BR', 'A gentileza não é superficial.', 'Ser gentil exige uma coragem profunda: a firmeza de pausar, a sabedoria de não reagir com aspereza e a paciência com o próprio ritmo de crescimento.', 'Em qual parte da sua rotina um pouco mais de ternura traria mais serenidade?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-10-11_en', '2026-10-11', 'en', 'A steadier place to land.', 'When the world is loud and demanding, your breath is a quiet sanctuary that is always available to you right where you sit.', 'What physical anchor helps you feel supported when your thoughts feel scattered?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-10-11_es', '2026-10-11', 'es', 'Un lugar más firme donde aterrizar.', 'Cuando el entorno es ruidoso y exigente, tu respiración es un refugio discreto que siempre está disponible justo donde estás.', '¿Qué apoyo físico te ayuda a sentir estabilidad cuando la mente está dispersa?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
INSERT OR REPLACE INTO affirmations (id, date, locale, affirmation, reflection, journal_prompt, grounding_practice_id, is_member_only, created_at) VALUES ('aff_2026-10-11_pt-BR', '2026-10-11', 'pt-BR', 'Um pouso mais sereno e seguro.', 'Quando o mundo ao redor parecer agitado demais, sua respiração é um refúgio simples e sempre presente no lugar onde você está.', 'Que detalhe ao seu redor ajuda a trazer firmeza quando a mente se perde em preocupações?', 'arrive', 0, '2026-09-23T10:40:44.471Z');
