-- Table: course_translations (9 rows)
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_compassion', 'en', 'Self-Compassion & Kindness Practices', 'Replacing harsh self-judgment with grounded, honest care you can actually use.', 'A structured 4-module journey into mindful presence, the universal nature of human difficulty, and practical ways to speak kindly to yourself in moments of crisis.', '["Master the three-part kindness pause in high-stress moments","Dismantle the myth that self-criticism leads to success","Cultivate emotional containers that prevent overwhelm"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_compassion', 'es', 'Prácticas de autocompasión y bondad', 'Sustituir el diálogo interno severo por un cuidado sincero y aplicable a la vida real.', 'Un recorrido en cuatro módulos para cultivar la presencia plena, comprender la fragilidad humana compartida y tratarse con paciencia durante los momentos difíciles.', '["Integrar la pausa de autocompasión en situaciones tensas","Comprender por qué la autocrítica constante agota tu energía","Crear espacios de descanso emocional en el día a día"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_compassion', 'pt-BR', 'Práticas de autocompaixão e gentileza', 'Transformando a autocrítica dura em um apoio sincero e realizável no cotidiano.', 'Uma jornada em quatro etapas para desenvolver presença, acolher as dificuldades humanas e falar consigo mesmo com respeito e paciência.', '["Aprender a pausa da gentileza para momentos de sobrecarga","Perceber que a autocrítica não é a chave para o crescimento","Construir hábitos diários de cuidado e respeito pelo seu corpo"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_acceptance', 'en', 'Radical Acceptance Foundations', 'Ending the exhaustion of fighting reality as it is right now.', 'Learn the life-changing practice of acknowledging reality without approval or surrender, opening the door to genuine healing and effective choice.', '["Distinguish acceptance from resignation or giving up","Recognize bodily indicators of bracing and resistance","Reclaim the energy currently spent arguing with what has already happened"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_acceptance', 'es', 'Fundamentos de la aceptación radical', 'Terminar con el desgaste de luchar contra lo que ya es una realidad.', 'Aprende a reconocer el presente con honestidad sin resignarte, abriendo camino a decisiones más conscientes y serenas.', '["Diferenciar la aceptación lúcida de la resignación pasiva","Detectar la tensión física asociada a la negación","Recuperar la energía que se gasta resistiendo lo inevitable"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_acceptance', 'pt-BR', 'Fundamentos da aceitação consciente', 'Encerrando o cansaço de lutar contra os fatos como eles são agora.', 'Descubra a prática transformadora de reconhecer a realidade presente para, então, escolher caminhos mais saudáveis e possíveis.', '["Diferenciar aceitação genuína de resignação sem esperança","Perceber como a resistência consome energia do corpo","Direcionar sua força para o que realmente está ao seu alcance"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_spiritual', 'en', 'Spiritual Reflection & Contemplative Support', 'Presence, listening, meaning-making, and deep ethical care across beliefs.', 'Explore ancient contemplative traditions, scripture and prayer in a grounded wellness context, and the sacred craft of companioning others through life’s deep seasons.', '["Establish a repeatable daily contemplative silence rhythm","Integrate faith traditions with somatic and emotional health","Hold quiet, non-judgmental space for friends and family"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_spiritual', 'es', 'Reflexión espiritual y acompañamiento contemplativo', 'Presencia, escucha profunda y cuidado ético en las distintas etapas de la vida.', 'Explora tradiciones contemplativas milenarias, la oración sincera y el arte de acompañar a otros en momentos de búsqueda o transición espiritual.', '["Establecer un momento diario de silencio y recogimiento","Integrar la vida de fe con el bienestar físico y emocional","Ofrecer una presencia comprensiva sin imponer dogmas"]');
INSERT OR REPLACE INTO course_translations (course_id, locale, title, subtitle, description, learning_outcomes) VALUES ('course_spiritual', 'pt-BR', 'Reflexão espiritual e cuidado contemplativo', 'Presença, escuta acolhedora e sentido para a caminhada.', 'Explore caminhos de oração, quietude e acolhimento espiritual com respeito, profundidade e equilíbrio emocional.', '["Criar um ritmo diário de oração e silêncio reparador","Unir a espiritualidade com o cuidado com a saúde mental","Acolher amigos e familiares com respeito e empatia"]');

