INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_comp_1', 'en', 'Understanding the Inner Voice', 'Examining why the human brain defaults to self-criticism and how to shift awareness.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_comp_1', 'es', 'Comprender la voz interior', 'Por qué la mente tiende a la autocrítica y cómo abrir espacio a la serenidad.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_comp_1', 'pt-BR', 'Compreendendo o diálogo interno', 'Por que nossa mente costuma ser dura e como cultivar mais afeto.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_acc_1', 'en', 'What Acceptance Is and Is Not', 'Clearing misconceptions about acceptance, resignation, and moral agreement.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_acc_1', 'es', 'Qué es y qué no es la aceptación', 'Aclarar ideas erróneas sobre la aceptación, el abandono y la resignación.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_acc_1', 'pt-BR', 'O que aceitação é e o que não é', 'Desfazendo mitos sobre aceitação, conformismo e resignação.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_spir_1', 'en', 'The Sacred Pause: Silence & Breath', 'Entering the quiet sanctuary where stillness becomes prayer.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_spir_1', 'es', 'La pausa sagrada: Silencio y aliento', 'Entrar en el refugio tranquilo donde la quietud se vuelve oración.');
INSERT OR REPLACE INTO module_translations (module_id, locale, title, description) VALUES ('mod_spir_1', 'pt-BR', 'A pausa sagrada: Silêncio e respiração', 'Entrando no refúgio tranquilo onde a quietude se transforma em oração.');

