-- Table: lesson_translations (12 rows)
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_comp_1', 'en', 'Arrival & Honest Inquiry', 'Welcome to this exploration. We begin not by trying to banish our critical thoughts, but by noticing the tone in which we speak to ourselves when things go wrong.', 'What words do you most frequently tell yourself when you make an everyday mistake?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_comp_1', 'es', 'Llegada e indagación sincera', 'Te damos la bienvenida. Comenzamos no luchando contra los pensamientos autocríticos, sino reconociendo el tono con el que nos hablamos cuando algo sale mal.', '¿Qué sueles decirte cuando cometes una pequeña equivocación en el día?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_comp_1', 'pt-BR', 'Chegada e escuta honesta', 'Boas-vindas a este aprendizado. Começamos sem forçar a positividade, apenas prestando atenção em como nos tratamos nos dias difíceis.', 'Quais frases costumam surgir na sua cabeça diante de um pequeno erro cotidiano?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_comp_2', 'en', 'The Three Components of Compassion', 'Dr. Kristin Neff’s pioneering research identifies three core pillars: Mindfulness, Common Humanity, and Self-Kindness.', 'Which of these three pillars feels most foreign or difficult for you right now?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_comp_2', 'es', 'Los tres pilares de la compasión', 'La investigación contemporánea destaca tres pilares: Presencia consciente, Humanidad compartida y Amabilidad sincera.', '¿Cuál de estos tres elementos te resulta más difícil de practicar hoy?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_comp_2', 'pt-BR', 'Os três pilares do cuidado', 'Estudos sobre autocompaixão identificam três eixos essenciais: Atenção plena, Humanidade compartilhada e Gentileza prática.', 'Qual desses três aspectos é o maior desafio para você hoje?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_acc_1', 'en', 'Acknowledging the Facts of Today', 'Acceptance does not mean you approve of what happened. It means you stop exhausting yourself by denying what has already occurred.', 'What fact about your current reality have you been resisting or trying to deny?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_acc_1', 'es', 'Reconocer la realidad presente', 'Aceptar no significa estar de acuerdo con lo sucedido, sino dejar de desgastarte negando lo que ya forma parte de los hechos.', '¿Qué hecho de tu vida presente te ha costado más reconocer?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_acc_1', 'pt-BR', 'Reconhecendo a realidade presente', 'Aceitar não significa aprovar o que aconteceu, mas parar de se esgotar brigando contra o que já se consolidou.', 'Qual aspecto da sua realidade atual você tem resistido em aceitar?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_spir_1', 'en', 'The Practice of Stillness and Gentle Arrival', 'Across centuries, contemplative traditions have recognized that God and peace are met not in frantic striving, but in the quiet stillness where the soul rests.', 'What happens in your body when you allow yourself five minutes of completely quiet rest?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_spir_1', 'es', 'La práctica del silencio y el descanso interior', 'A lo largo de los siglos, la tradición contemplativa nos recuerda que la paz se encuentra en la quietud profunda donde el alma reposa con confianza.', '¿Qué experimenta tu cuerpo cuando le regalas cinco minutos de silencio absoluto?', NULL);
INSERT OR REPLACE INTO lesson_translations (lesson_id, locale, title, content, reflection_prompt, worksheet_reference) VALUES ('les_spir_1', 'pt-BR', 'A prática da quietude e o descanso da alma', 'Ao longo dos séculos, tradições contemplativas mostram que a serenidade se revela quando silenciamos o excesso de ruído e descansamos na presença.', 'O que o seu corpo sente quando você se permite cinco minutos de silêncio e repouso?', NULL);

