-- Table: quiz_translations (18 rows)
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_rest', 'en', 'What Kind of Rest Do I Need?', 'A gentle self-check on the 7 distinct types of human restoration.', 'Sleep is not the only way to recover. Discover whether your body, mind, senses, emotions, or spirit are asking for care right now.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_rest', 'es', '¿Qué tipo de descanso necesito hoy?', 'Una pausa reflexiva sobre las siete formas de recuperación personal.', 'Dormir no es la única manera de reponer fuerzas. Descubre si tu mente, tus sentidos, tu cuerpo o tu espíritu están pidiendo un respiro.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_rest', 'pt-BR', 'De que tipo de descanso eu preciso hoje?', 'Uma reflexão honesta sobre as diferentes formas de recuperação.', 'Dormir não é a única maneira de descansar. Veja se sua mente, suas emoções, seus sentidos ou seu espírito estão pedindo uma pausa.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_compassion', 'en', 'Self-Compassion Check-In', 'Reflecting on your inner conversation in moments of challenge.', 'Notice how you respond when you stumble, and discover simple somatic tools to bring more warmth to yourself.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_compassion', 'es', 'Revisión de la autocompasión', 'Cómo te hablas cuando las cosas no salen como esperabas.', 'Observa tus reacciones interiores ante el error y descubre prácticas suaves para tratarte con mayor paciencia.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_compassion', 'pt-BR', 'Check-in de autocompaixão', 'Como anda sua conversa consigo mesmo nos momentos difíceis.', 'Perceba a maneira como você reage aos próprios tropeços e encontre formas gentis de se acolher.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_stress', 'en', 'Stress & Overwhelm Reflection', 'Listening to the warning signals of your nervous system.', 'A non-clinical check on the physical, emotional, and relational signals of an overstressed body.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_stress', 'es', 'Reflexión sobre el estrés y la sobrecarga', 'Escuchar las señales sutiles de tu cuerpo.', 'Un chequeo no clínico para reconocer cuándo el cuerpo está pidiendo una pausa urgente.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_stress', 'pt-BR', 'Reflexão sobre estresse e sobrecarga', 'Ouvindo os alertas gentis do seu corpo.', 'Uma reflexão educativa para identificar onde a tensão está acumulada e encontrar alívio.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_grounding', 'en', 'Grounding Style Finder', 'Discovering whether somatic, sensory, cognitive, or nature anchors serve you best.', 'Find out what kind of anchoring practice helps you land most reliably when life gets overwhelming.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_grounding', 'es', 'Descubre tu estilo de enraizamiento', 'Qué anclajes —somáticos, sensoriales o en la naturaleza— te ayudan mejor.', 'Conoce qué tipo de ejercicio de calma te ofrece mayor estabilidad cuando las cosas se complican.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_grounding', 'pt-BR', 'Descubra seu estilo de aterramento', 'Quais apoios — corporais, sensoriais ou na natureza — funcionam melhor para você.', 'Entenda qual prática de presença traz mais equilíbrio para o seu dia a dia.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_habits', 'en', 'Daily Habits Reflection', 'Honoring small, sustainable rhythms over heroic overhauls.', 'Reflect on how your morning, midday, and twilight rhythms currently support your peace.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_habits', 'es', 'Reflexión sobre los hábitos cotidianos', 'Valorar los pequeños ritmos sostenibles en lugar de cambios bruscos.', 'Examina con cariño cómo tus momentos de la mañana y de la tarde cuidan tu serenidad.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_habits', 'pt-BR', 'Reflexão sobre hábitos cotidianos', 'Pequenos passos constantes em vez de exigências heroicas.', 'Perceba como seus momentos de pausa pela manhã e ao entardecer apoiam o seu bem-estar.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_boundaries', 'en', 'Boundaries & Energy Check-In', 'Noticing where your energy leaks and practicing clean, honest limits.', 'A thoughtful reflection on people-pleasing, over-explaining, and how to protect your peace with warm clarity.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_boundaries', 'es', 'Revisión de límites y energía personal', 'Identificar dónde se dispersa tu energía y cuidar tus espacios.', 'Una mirada sincera sobre la necesidad de complacer a otros y cómo establecer límites con serenidad.');
INSERT OR REPLACE INTO quiz_translations (quiz_id, locale, title, subtitle, description) VALUES ('quiz_boundaries', 'pt-BR', 'Check-in de limites e energia', 'Percebendo onde sua energia escapa e cuidando do seu tempo.', 'Uma reflexão afetuosa sobre a dificuldade de dizer não e como colocar limites claros com gentileza.');

-- Table: quiz_questions (9 rows)
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_rest_1_en', 'quiz_rest', 1, 'en', 'When you imagine true relief right now, what does your body crave first?', '[{"label":"Closing my eyes in complete silence without any screen or light","tag":"sensory"},{"label":"Unclenched muscles, a warm blanket, and stretching out to sleep","tag":"physical"},{"label":"Not having to make a single decision or answer anyone for an hour","tag":"mental"},{"label":"An honest conversation where I do not have to put on a brave face","tag":"emotional"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_rest_1_es', 'quiz_rest', 1, 'es', 'Al imaginar un verdadero alivio en este momento, ¿qué te pide el cuerpo en primer lugar?', '[{"label":"Cerrar los ojos en silencio total, lejos de pantallas o luces intensas","tag":"sensory"},{"label":"Aflojar los músculos, una manta tibia y descansar el cuerpo","tag":"physical"},{"label":"No tener que tomar ninguna decisión ni responder mensajes por un rato","tag":"mental"},{"label":"Una conversación sincera donde no tenga que fingir que todo marcha bien","tag":"emotional"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_rest_1_pt-BR', 'quiz_rest', 1, 'pt-BR', 'Quando você pensa em alívio agora, o que seu corpo pede primeiro?', '[{"label":"Fechar os olhos no silêncio, sem luzes nem notificações","tag":"sensory"},{"label":"Soltar os músculos, uma coberta quentinha e relaxar o corpo","tag":"physical"},{"label":"Não ter que tomar decisões nem responder ninguém por uma hora","tag":"mental"},{"label":"Uma conversa sincera onde eu não precise parecer forte o tempo todo","tag":"emotional"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_rest_2_en', 'quiz_rest', 2, 'en', 'What has been the greatest source of fatigue for you over the last few days?', '[{"label":"Constant sensory input, notifications, and visual clutter","tag":"sensory"},{"label":"Physical exertion, poor sleep, or carrying physical tension","tag":"physical"},{"label":"Endless mental to-do lists, problem-solving, and tab-switching","tag":"mental"},{"label":"Managing other people’s feelings or keeping my own feelings bottled up","tag":"emotional"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_rest_2_es', 'quiz_rest', 2, 'es', '¿Cuál ha sido la mayor fuente de cansancio para ti en los últimos días?', '[{"label":"Estímulos continuos, alertas en el teléfono y ruido ambiental","tag":"sensory"},{"label":"Tensión muscular, pocas horas de sueño o malestar físico","tag":"physical"},{"label":"Listas interminables de tareas y preocupaciones por resolver","tag":"mental"},{"label":"Atender las emociones de los demás o guardar en silencio lo que siento","tag":"emotional"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_rest_2_pt-BR', 'quiz_rest', 2, 'pt-BR', 'O que mais tem consumido sua energia nos últimos dias?', '[{"label":"Estímulos visuais constantes, barulhos e notificações do celular","tag":"sensory"},{"label":"Falta de sono, postura cansada ou tensão física acumulada","tag":"physical"},{"label":"Pensamentos acelerados e listas intermináveis de afazeres","tag":"mental"},{"label":"Cuidar das expectativas alheias e engolir os próprios sentimentos","tag":"emotional"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_comp_1_en', 'quiz_compassion', 1, 'en', 'When you make an unintentional mistake in front of others, what is your immediate reflex?', '[{"label":"Harsh internal lecturing: \"How could I have been so foolish?\"","tag":"critical"},{"label":"Numbness or wanting to disappear completely from the room","tag":"withdrawn"},{"label":"A quiet breath acknowledging: \"I am human, and mistakes happen to everyone.\"","tag":"compassionate"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_comp_1_es', 'quiz_compassion', 1, 'es', 'Cuando cometes un error involuntario ante los demás, ¿cuál es tu primera reacción interna?', '[{"label":"Reproches duros: \"¿Cómo pude haber hecho semejante tontería?\"","tag":"critical"},{"label":"Ganas de desaparecer del lugar y desconectarme por completo","tag":"withdrawn"},{"label":"Una respiración tranquila recordando: \"Soy humano y esto le pasa a cualquiera.\"","tag":"compassionate"}]');
INSERT OR REPLACE INTO quiz_questions (id, quiz_id, sort_order, locale, question, options) VALUES ('q_comp_1_pt-BR', 'quiz_compassion', 1, 'pt-BR', 'Quando você comete um erro sem querer diante de outras pessoas, qual é seu primeiro reflexo?', '[{"label":"Crítica dura: \"Como fui capaz de errar nisso?\"","tag":"critical"},{"label":"Vontade de sumir do ambiente e se fechar","tag":"withdrawn"},{"label":"Uma pausa serena lembrando: \"Errar faz parte da vida de todos nós.\"","tag":"compassionate"}]');

