-- Table: circle_space_translations (12 rows)
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('gentle-check-in', 'en', 'Gentle Check-In', 'A quiet, unhurried space to say how you are actually doing today without having to perform or explain.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('gentle-check-in', 'es', 'Pausa sincera', 'Un espacio tranquilo para compartir cómo te encuentras hoy, sin apariencias ni justificaciones.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('gentle-check-in', 'pt-BR', 'Check-in acolhedor', 'Um cantinho tranquilo para contar como você está de verdade hoje, sem cobranças nem filtros.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('practice-together', 'en', 'Practice Together', 'Sharing notes, questions, and reflections on our 12 grounding, emotion, and boundary practices.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('practice-together', 'es', 'Practicar en compañía', 'Reflexiones y experiencias compartidas sobre los ejercicios de enraizamiento y calma.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('practice-together', 'pt-BR', 'Praticar juntos', 'Trocas de experiências sobre os exercícios de respiração, limites e serenidade.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('being-with-it', 'en', 'Being With It', 'Holding space for grief, sorrow, transitions, and the questions that don’t have neat answers.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('being-with-it', 'es', 'Acompañar lo difícil', 'Un lugar respetuoso para el dolor, los duelos y las etapas de incertidumbre en la vida.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('being-with-it', 'pt-BR', 'Estar presente com a dor', 'Espaço de respeito para o luto, as saudades e as dúvidas que não têm respostas fáceis.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('quiet-wins', 'en', 'Quiet Wins', 'Celebrating tiny, ordinary victories: saying a clean no, taking a slow breath, stepping outside.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('quiet-wins', 'es', 'Pequeñas victorias', 'Celebrar los avances cotidianos: poner un límite amable, respirar con calma, descansar.');
INSERT OR REPLACE INTO circle_space_translations (space_id, locale, name, description) VALUES ('quiet-wins', 'pt-BR', 'Pequenas vitórias', 'Reconhecendo as conquistas sutis do dia a dia: dizer um não honesto, respirar fundo e pausar.');

