-- Table: product_translations (21 rows)
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_workbook', 'en', 'The Self-Compassion Workbook', '11-page printable companion for tender moments', 'A beautifully formatted guide with structured prompts, reflective exercises, and practical somatic grounding tools.', '["11 printable PDF pages","Guided reflection prompts and exercises","Immediate protected digital download"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_workbook', 'es', 'Cuaderno de autocompasión y ternura', 'Guía imprimible de 11 páginas para momentos difíciles', 'Un material cuidado con ejercicios reflexivos, preguntas orientadoras y prácticas de calma somática para imprimir en casa.', '["11 páginas en PDF para imprimir","Plantillas de reflexión personal y seguimiento","Descarga digital inmediata y segura"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_workbook', 'pt-BR', 'Caderno de autocompaixão e afeto', 'Guia de 11 páginas em PDF para imprimir', 'Um companheiro afetuoso com exercícios práticos, páginas de reflexão e pausas de respiração para momentos desafiadores.', '["11 páginas formatadas para impressão","Roteiros de escrita terapêutica e acolhimento","Acesso digital imediato e seguro"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_tracker', 'en', '30-Day Kindness Habit Tracker', 'Simple daily micro-practices without guilt or pressure', 'Track small, honest repetitions of care: stepping outdoors, unclenched shoulders, honest boundaries, and slow tea.', '["Printable one-month circular tracker","Daily inspiration card deck cutouts","Tips for habit-stacking with grace"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_tracker', 'es', 'Registro de hábitos de bondad (30 días)', 'Pequeñas prácticas diarias sin culpa ni exigencias', 'Acompaña tus momentos de pausa: salir al aire libre, soltar tensiones, saborear un té y agradecer.', '["Lámina circular imprimible de 30 días","Tarjetas recortables con recordatorios","Enfoque libre de exigencias o castigos"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_tracker', 'pt-BR', 'Acompanhamento de 30 dias de gentileza', 'Pequenos hábitos diários com leveza e sem cobranças', 'Registre gestos simples de cuidado: respirar ar puro, soltar os ombros, preparar um chá morno e pausar.', '["Guia circular de 30 dias para imprimir","Cartões de bolso com frases acolhedoras","Orientação prática para cultivar bons momentos"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_practice_cards', 'en', 'Printable Somatic Practice Cards', '24 pocket-sized reminder cards for grounding anywhere', 'Keep quick, accessible grounding techniques on your desk, in your bag, or on your refrigerator door.', '["24 illustrated pocket cards (PDF format)","Step-by-step instructions on each card","Formatted for standard home printing"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_practice_cards', 'es', 'Tarjetas impresas de calma y enraizamiento', '24 tarjetas de bolsillo para llevar serenidad a donde vayas', 'Ten a mano ejercicios breves de respiración y presencia en tu bolso, escritorio o rincón favorito.', '["24 tarjetas ilustradas listas para imprimir","Instrucciones claras y directas en cada una","Formato estándar para hojas carta o A4"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_practice_cards', 'pt-BR', 'Cartões de práticas somáticas para imprimir', '24 cartões de bolso com pausas de serenidade', 'Mantenha exercícios rápidos de respiração e presença na sua bolsa, mesa de trabalho ou cabeceira.', '["24 cartões ilustrados em alta resolução","Passo a passo simples em cada cartão","Pronto para impressão caseira"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_sheets', 'en', 'Emotional Support Quick Sheets', '5 printable one-page reference sheets', 'Concise reference sheets for listening, setting boundaries, grounding, crisis moments, and knowing when to refer someone on.', '["5 printable reference sheets","Covers listening, boundaries, grounding, crisis, and referral","Immediate PDF download"]');
INSERT OR REPLACE INTO product_translations (product_id, locale, name, tagline, description, details) VALUES ('prod_sheets', 'es', 'Hojas rápidas de apoyo emocional', '5 láminas de consulta rápida para momentos de tensión', 'Hojas claras y concisas para escuchar, poner límites, anclarse en el cuerpo, momentos de crisis y saber cuándo derivar a otra ayuda.', '["5 láminas imprimibles","Escucha, límites, anclaje, crisis y derivación","Descarga digital inmediata"]');
